    ('a6f66111-c0d1-4c01-a49a-eb2d476a33d0'::uuid, 'period_name', '500 BC - 1 AD', NULL, 'fields-wd1-2026-09-26b-s008:a6f66111-c0d1-4c01-a49a-eb2d476a33d0:period_name', 'fields-wd1-2026-09-26b-s008 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('a6f66111-c0d1-4c01-a49a-eb2d476a33d0'::uuid, 'period_start', '-424', NULL, 'fields-wd1-2026-09-26b-s008:a6f66111-c0d1-4c01-a49a-eb2d476a33d0:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-clear): ''-424'' -> None', '[{"source": "WD1 decision (counted, round 1, wd1-r1-b0011)", "decision": "clear", "status": "MISSING", "reasoning": "Only the Wikipedia family (en/el articles, Wikidata) states a date for the Treasury of the Acanthians at Delphi (built from spoils after Brasidas won Acanthus over in 424 BC, perhaps after his death in 422 BC, with the article itself noting opposing views); the one scholarly source that puts it in the late 420s (Sears, SCS abstract) refuses the checker (403), and Plutarch gives no date, so no second readable independent source dates the start.", "value_page": null}]'::jsonb),
    ('a6f66111-c0d1-4c01-a49a-eb2d476a33d0'::uuid, 'site_type', 'Megalithic structures', NULL, 'fields-wd1-2026-09-26b-s008:a6f66111-c0d1-4c01-a49a-eb2d476a33d0:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-clear): ''Megalithic structures'' -> None', '[{"source": "WD1 decision (counted, round 1, wd1-r1-b0011)", "decision": "clear", "status": "CONFLICT", "reasoning": "Wikipedia and Plutarch (Lysander 1) call the building a treasury in the sanctuary of Apollo at Delphi, but no canonical type names a treasury and no readable source calls it a monument, temple or sanctuary itself; the stored Megalithic structures is contradicted by every source, so the field is emptied.", "value_page": null}]'::jsonb),
    ('a71d8ba8-3ca0-4845-a519-609b286b4eb3'::uuid, 'geom', '0101000020E61000008DDDF7E0A94C4040CED08C8662453940', 'SRID=4326;POINT(32.79778 25.11889)', 'fields-wd1-2026-09-26b-s008:a71d8ba8-3ca0-4845-a519-609b286b4eb3:geom', 'fields-wd1-2026-09-26b-s008 (wd1-point): 25.27103463113672, 32.59893428900532 -> 25.11889, 32.79778', '[{"source": "https://en.wikipedia.org/wiki/Elkab", "url": "https://en.wikipedia.org/wiki/Elkab", "quote": "25.11889°N 32.79778°E", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=6336062", "url": "https://www.megalithic.co.uk/article.php?sid=6336062", "quote": "Latitude: 25.119719N Longitude: 32.798219E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0022)", "decision": "replace", "status": "CONFLICT", "reasoning": "The English Wikipedia article places Elkab at 25.11889, 32.79778 and the Megalithic Portal''s El Kab [Necheb] entry at 25.119719, 32.798219, about 0.1 km apart on the east bank of the Nile; the stored point lies about 26 km away near Esna on the west bank, so it is replaced.", "value_page": null}]'::jsonb),
