    ('a71d8ba8-3ca0-4845-a519-609b286b4eb3'::uuid, 'period_name', '3000 - 1500 BC', '< 4500 BC', 'fields-wd1-2026-09-26b-s008:a71d8ba8-3ca0-4845-a519-609b286b4eb3:period_name', 'fields-wd1-2026-09-26b-s008 (wd1-derive-period-name): period_start -6400 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-6400) = ''< 4500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('a71d8ba8-3ca0-4845-a519-609b286b4eb3'::uuid, 'period_start', '-3000', '-6400', 'fields-wd1-2026-09-26b-s008:a71d8ba8-3ca0-4845-a519-609b286b4eb3:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''-3000'' -> ''-6400''', '[{"source": "https://egyptartefacts.griffith.ox.ac.uk/node/1094/", "url": "https://egyptartefacts.griffith.ox.ac.uk/node/1094/", "quote": "El-Kab was the site of human activity from 6000 BCE but was an important Predynastic and Early Dynastic settlement in parallel with Hierakonpolis, which is located across the Nile.", "outcome": "found"}, {"source": "https://talesfromthetwolands.org/2020/04/01/nekheb/", "url": "https://talesfromthetwolands.org/2020/04/01/nekheb/", "quote": "Three layers of camps were found one on top of the other dating between c. 6400 BCE and c. 5980 BCE on the riverbank of the ancient channel of the Nile.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0004)", "decision": "replace", "status": "MISSING", "reasoning": "The Griffith Institute (Oxford) says El-Kab was a site of human activity from 6000 BCE, and the Tales from the Two Lands site reports the earliest Elkabian camps at El Kab radiocarbon-dated from c. 6400 BCE; both put the start of the site far earlier than the stored 3000 - 1500 BC bucket, in the < 4500 BC bucket, and the earliest dated occupation is c. 6400 BCE.", "value_page": null}]'::jsonb),
    ('a71d8ba8-3ca0-4845-a519-609b286b4eb3'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/El_Kab', 'https://en.wikipedia.org/wiki/Elkab', 'fields-wd1-2026-09-26b-s008:a71d8ba8-3ca0-4845-a519-609b286b4eb3:source_url', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''https://en.wikipedia.org/wiki/El_Kab'' -> ''https://en.wikipedia.org/wiki/Elkab''', '[{"source": "https://en.wikipedia.org/wiki/Elkab", "url": "https://en.wikipedia.org/wiki/Elkab", "quote": "also spelled El-Kab or El Kab", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Elkab", "url": "https://en.wikipedia.org/wiki/Elkab", "quote": "Elkab was called Nekheb in the Egyptian language", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=6336062", "url": "https://www.megalithic.co.uk/article.php?sid=6336062", "quote": "Site Name: El Kab Alternative Name: Necheb Country: Egypt", "outcome": "found"}, {"source": "https://www.kmkg-mrah.be/en/scientific-research/elkab", "url": "https://www.kmkg-mrah.be/en/scientific-research/elkab", "quote": "researchers of the Royal Museums of Art and History have been conducting archaeological and epigraphical research at Elkab a site located on the east bank of the Nile, some 80 km south of Luxor.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0022)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL El_Kab is a redirect to the English Wikipedia article Elkab (also spelled El Kab), which is about this archaeological site, ancient Nekheb; the article''s own URL replaces the redirect, and the Megalithic Portal and the Royal Museums of Art and History describe the same site on the east bank of the Nile south of Luxor.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Elkab", "unreadable": false, "wikibase_item": "Q287705"}}]'::jsonb),
    ('a744c90a-9a6a-4c23-ae16-ce84becaaa9a'::uuid, 'period_name', '500 - 1000 AD', '< 4500 BC', 'fields-wd1-2026-09-26b-s008:a744c90a-9a6a-4c23-ae16-ce84becaaa9a:period_name', 'fields-wd1-2026-09-26b-s008 (wd1-derive-period-name): period_start -7000 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-7000) = ''< 4500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('a744c90a-9a6a-4c23-ae16-ce84becaaa9a'::uuid, 'period_start', '500', '-7000', 'fields-wd1-2026-09-26b-s008:a744c90a-9a6a-4c23-ae16-ce84becaaa9a:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''500'' -> ''-7000''', '[{"source": "https://lugares.inah.gob.mx/es/node/4414", "url": "https://lugares.inah.gob.mx/es/node/4414", "quote": "Destaca la presencia de puntas de proyectil del tipo Meserve y un hacha de mano fechadas hacia el 7000 a.C.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Huapalcalco", "url": "https://en.wikipedia.org/wiki/Huapalcalco", "quote": "have been dated to around 9000 BCE", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0096)", "decision": "replace", "status": "MISSING", "reasoning": "INAH names five occupations of Huapalcalco, the first prehistoric, with Meserve points and a hand axe dated c. 7000 BC; Wikipedia dates the cave paintings of the Huapalcalco plateau to c. 9000 BCE. The site''s first occupation therefore lies before 4500 BC, not in 500-1000 AD; the pyramid itself is a later (Classic/Epiclassic) phase.", "value_page": null}]'::jsonb),
