    ('a791798d-8ed0-4134-bd0d-de1deaef99a1'::uuid, 'geom', '0101000020E610000011CA1D6FBCFB3640E6D31CAF15B14340', 'SRID=4326;POINT(22.93332 39.363868)', 'fields-wd1-2026-09-26b-s008:a791798d-8ed0-4134-bd0d-de1deaef99a1:geom', 'fields-wd1-2026-09-26b-s008 (wd1-point): 39.38347424419025, 22.983344025395187 -> 39.363868, 22.93332', '[{"source": "https://helladic.info/MAPC/pkey_report_wparam.php?place=C1269", "url": "https://helladic.info/MAPC/pkey_report_wparam.php?place=C1269", "quote": "39.363868, 22.93332", "outcome": "found"}, {"source": "https://www.wikidata.org/wiki/Q662613", "url": "https://www.wikidata.org/wiki/Q662613", "quote": "39°21''47\"N, 22°56''2\"E", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/8912965975", "url": "https://www.openstreetmap.org/node/8912965975", "quote": "39.3650267, 22.9332955", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0066)", "decision": "replace", "status": "CONFLICT", "reasoning": "Ancient Iolcus is the Kastro (Palaia) mound at the west end of modern Volos; the Mycenaean Atlas, Wikidata''s first coordinate and the OpenStreetMap node of the Kastro Palaion all place it about 5 km south-west of the stored point, which marks the modern municipal unit of Iolkos (Ano Volos, Anakasia).", "value_page": null}]'::jsonb),
