    ('a791798d-8ed0-4134-bd0d-de1deaef99a1'::uuid, 'period_name', '1500 - 500 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s008:a791798d-8ed0-4134-bd0d-de1deaef99a1:period_name', 'fields-wd1-2026-09-26b-s008 (wd1-derive-period-name): period_start -3000 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-3000) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('a791798d-8ed0-4134-bd0d-de1deaef99a1'::uuid, 'period_start', '-1000', '-3000', 'fields-wd1-2026-09-26b-s008:a791798d-8ed0-4134-bd0d-de1deaef99a1:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''-1000'' -> ''-3000''', '[{"source": "https://e-thessalia.gr/kastro-palaia-iolkos-ena-diachroniko-emporiko-thalassio-kentro-tis-mesogeioy-5000-chronon/", "url": "https://e-thessalia.gr/kastro-palaia-iolkos-ena-diachroniko-emporiko-thalassio-kentro-tis-mesogeioy-5000-chronon/", "quote": "έφερε στο φως την Ιωλκό, οργανωμένο οικισμό της εποχής του Χαλκού (3.000 – 1100 π. Χ.)", "outcome": "found"}, {"source": "https://helladic.info/MAPC/pkey_report_wparam.php?place=C1269", "url": "https://helladic.info/MAPC/pkey_report_wparam.php?place=C1269", "quote": "Early Bronze Age I: (3300 BC - 3000 BC)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0066)", "decision": "replace", "status": "MISSING", "reasoning": "The Kastro Palaia settlement identified with Iolcus has been occupied continuously since Early Bronze Age I; e-thessalia dates the Bronze Age settlement from 3000 BC and the Mycenaean Atlas lists Early Bronze Age I (3300-3000 BC) as its first phase, so the start is c. 3000 BC, not the stored 1000 BC.", "value_page": null}]'::jsonb),
    ('a7ea17b2-3760-4724-9672-38bc0687da0c'::uuid, 'site_type', 'City/town/settlement', 'Village', 'fields-wd1-2026-09-26b-s008:a7ea17b2-3760-4724-9672-38bc0687da0c:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''City/town/settlement'' -> ''Village''', '[{"source": "https://www.illesbalears.travel/en/mallorca/archaeological-site-poblat-talaiotic-de-ses-paisses", "url": "https://www.illesbalears.travel/en/mallorca/archaeological-site-poblat-talaiotic-de-ses-paisses", "quote": "The talayotic village of Ses Païsses dates back to around the year 1000 BCE, and is one of the most extensive and best conserved settlements on Majorca.", "outcome": "found"}, {"source": "https://www.arta.cat/ajuntament/fitxaServeis.php?id=100", "url": "https://www.arta.cat/ajuntament/fitxaServeis.php?id=100", "quote": "Ses Païsses és un dels poblats talaiòtics més ben conservats de Mallorca.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0133)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Balearic government calls Ses Païsses a talayotic village and the Artà council one of the best-preserved talayotic villages (poblats) of Majorca; a walled prehistoric village of 13,500 m2 is a Village, more specific than the combined City/town/settlement.", "value_page": null}]'::jsonb),
