    ('a8333fc8-7376-4362-b1e5-194d7475ab02'::uuid, 'period_start', '1', NULL, 'fields-wd1-2026-09-26b-s008:a8333fc8-7376-4362-b1e5-194d7475ab02:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-clear): ''1'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0043)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia says only that the road linked the Roman towns and may have predated the Roman occupation; neither it nor Vici.org, the Tadley history society or the Stratford sub Castle pages give a year or century for its construction, so no attested start can be quoted.", "value_page": null}]'::jsonb),
