    ('a88980f8-c949-4f48-94c6-0185f01a6862'::uuid, 'site_type', 'Temple complex', 'Sanctuary', 'fields-wd1-2026-09-26b-s008:a88980f8-c949-4f48-94c6-0185f01a6862:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''Temple complex'' -> ''Sanctuary''', '[{"source": "https://www.lykaionexcavation.org/site/", "url": "https://www.lykaionexcavation.org/site/", "quote": "In the ancient Greek region of Arcadia in the southwestern Peloponnesos, the sanctuary of Zeus on Mt. Lykaion stands out for its great fame, mysterious rituals and wide-ranging significance.", "outcome": "found"}, {"source": "https://topostext.org/place/375220SLyk", "url": "https://topostext.org/place/375220SLyk", "quote": "Zeus Lykaios, sanctuary with stadium/hippodrome, Mt. Lykaio above Ano Karyes, Arkadia Peloponnese", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0068)", "decision": "replace", "status": "CONFLICT", "reasoning": "The excavation project and ToposText describe the site as the sanctuary of Zeus Lykaios - an open-air ash altar and temenos on the peak with a lower sanctuary of stadium, hippodrome, stoa and fountain houses - with no temple; Sanctuary is the canonical type that holds, not Temple complex.", "value_page": null}]'::jsonb),
    ('a88980f8-c949-4f48-94c6-0185f01a6862'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Mount_Lykaion', 'https://www.lykaionexcavation.org/site/', 'fields-wd1-2026-09-26b-s008:a88980f8-c949-4f48-94c6-0185f01a6862:source_url', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''https://en.wikipedia.org/wiki/Mount_Lykaion'' -> ''https://www.lykaionexcavation.org/site/''', '[{"source": "https://www.lykaionexcavation.org/site/", "url": "https://www.lykaionexcavation.org/site/", "quote": "In the ancient Greek region of Arcadia in the southwestern Peloponnesos, the sanctuary of Zeus on Mt. Lykaion stands out for its great fame, mysterious rituals and wide-ranging significance.", "outcome": "found"}, {"source": "https://topostext.org/place/375220SLyk", "url": "https://topostext.org/place/375220SLyk", "quote": "Zeus Lykaios, sanctuary with stadium/hippodrome, Mt. Lykaio above Ano Karyes, Arkadia Peloponnese", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0068)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is about the mountain, and the sanctuary has no Wikipedia article of its own (its Wikidata item Q111046342 has no sitelinks; ''Lykaia'' is the festival). The Mt. Lykaion Excavation and Survey Project''s page ''The Site'' is devoted to the sanctuary of Zeus itself, which ToposText also records as a place of its own.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
