    ('aad935a4-efbd-4133-94ac-ce7d12789e9c'::uuid, 'period_start', '1', '-100', 'fields-wd1-2026-09-26b-s008:aad935a4-efbd-4133-94ac-ce7d12789e9c:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''1'' -> ''-100''', '[{"source": "https://en.wikipedia.org/wiki/Torre_del_Greco", "url": "https://en.wikipedia.org/wiki/Torre_del_Greco", "quote": "The nearby Roman Villa Sora[3] was a large and sumptuous residence with terraces down to the beach and overlooking the sea from its 150m-long frontage, dating from the 1st c. BC, whose excavated remains can be seen today.", "outcome": "found"}, {"source": "https://ercolano.cultura.gov.it/villa-sora-the-discoveries-of-the-latest-excavation-campaign/?lang=en", "url": "https://ercolano.cultura.gov.it/villa-sora-the-discoveries-of-the-latest-excavation-campaign/?lang=en", "quote": "Constructed around the mid-1st century BC and subsequently modified, the complex extended along the shoreline", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0089)", "decision": "replace", "status": "MISSING", "reasoning": "The earliest securely dated remains at Torre del Greco are those of the Roman maritime Villa Sora, built in the (mid-)1st century BC according to Wikipedia and the Herculaneum Archaeological Park; the town''s documented history before that is lacking. The 1st century BC lies in the 500 BC - 1 AD bucket, not the stored 1 - 500 AD one.", "value_page": null}]'::jsonb),
