    ('ab077874-2a7f-4add-adec-8cb42e9e9561'::uuid, 'period_start', '1', '-2000', 'fields-wd1-2026-09-26b-s008:ab077874-2a7f-4add-adec-8cb42e9e9561:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''1'' -> ''-2000''', '[{"source": "https://archeologie.culture.gouv.fr/monde/en/hegra", "url": "https://archeologie.culture.gouv.fr/monde/en/hegra", "quote": "Period of occupation 2nd millennium BCE - contemporary period", "outcome": "found"}, {"source": "https://hegraconservation.com/the-history-of-hegra/", "url": "https://hegraconservation.com/the-history-of-hegra/", "quote": "Some cairn tombs, that is burials covered by a heap of earth or stones dating between the end of the 3rd and beginning of the 2nd millennium BC, are the first remains of human activities detected on the Hegra site", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0121)", "decision": "replace", "status": "MISSING", "reasoning": "The French ministry of culture''s page on the French-Saudi Hegra project dates the site''s occupation from the 2nd millennium BCE. Hegra Conservation names Bronze Age cairn tombs of the late 3rd to early 2nd millennium BC as the first human remains on the site. The start is c. 2000 BC, in the 3000 - 1500 BC bucket, not the stored 1 - 500 AD.", "value_page": null}]'::jsonb),
    ('ab077874-2a7f-4add-adec-8cb42e9e9561'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Hegra_(Mada%27in_Salih)', 'https://en.wikipedia.org/wiki/Hegra', 'fields-wd1-2026-09-26b-s008:ab077874-2a7f-4add-adec-8cb42e9e9561:source_url', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''https://en.wikipedia.org/wiki/Hegra_(Mada%27in_Salih)'' -> ''https://en.wikipedia.org/wiki/Hegra''', '[{"source": "https://en.wikipedia.org/wiki/Hegra", "url": "https://en.wikipedia.org/wiki/Hegra", "quote": "Multiple Nabataean Tombs in Hegra (Madain Saleh)", "outcome": "found"}, {"source": "https://archeologie.culture.gouv.fr/monde/en/hegra", "url": "https://archeologie.culture.gouv.fr/monde/en/hegra", "quote": "Hegra, often called Madain Salih, is an archaeological site in the mountains of Hijaz", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0121)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL Hegra_(Mada''in_Salih) is a redirect to the article ''Hegra'', which is the site''s own English Wikipedia article and calls it Hegra (Madain Saleh). The French ministry of culture names the same site Hegra or Madain Salih, so the value becomes the article''s own URL.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Hegra", "unreadable": false, "wikibase_item": "Q27356"}}]'::jsonb),
