    ('ab80e2e4-7195-48ad-84fc-582925fe9504'::uuid, 'period_start', '-3000', '-1500', 'fields-wd1-2026-09-26b-s008:ab80e2e4-7195-48ad-84fc-582925fe9504:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''-3000'' -> ''-1500''', '[{"source": "https://link.springer.com/article/10.1007/s12231-018-9402-x", "url": "https://link.springer.com/article/10.1007/s12231-018-9402-x", "quote": "The Gramalote site is an early Initial Period (1500–1200 B.C.E.) fishing village located in the Moche valley in northern Peru.", "outcome": "found"}, {"source": "https://people.clas.ufl.edu/ogabriel-prietob/publications/", "url": "https://people.clas.ufl.edu/ogabriel-prietob/publications/", "quote": "Gramalote, an early Initial Period (1500-1200 cal. B.C.) maritime community, North Coast of Peru.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0112)", "decision": "replace", "status": "MISSING", "reasoning": "The excavation publications (Economic Botany 2018; the excavator Gabriel Prieto''s radiocarbon-dated studies listed on his University of Florida page) date the occupation of Gramalote to 1500-1200 cal BC; Wikipedia''s ''2000 BC'' is not supported by the excavator, so the start is c. 1500 BC, in the 1500-500 BC bucket rather than the stored 3000-1500 BC.", "value_page": null}]'::jsonb),
