    ('ac628dfb-ee59-4329-84dd-d5358e0adeb3'::uuid, 'period_start', '-3000', '-500', 'fields-wd1-2026-09-26b-s008:ac628dfb-ee59-4329-84dd-d5358e0adeb3:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''-3000'' -> ''-500''', '[{"source": "https://lycianway.co.uk/culture/cyaneae-kyaneai", "url": "https://lycianway.co.uk/culture/cyaneae-kyaneai", "quote": "Settlement began here in the fifth century BC, when Kyaneai was one of several dynastic seats in the Yavu highlands", "outcome": "found"}, {"source": "https://uni-tuebingen.de/fakultaeten/philosophische-fakultaet/fachbereiche/geschichtswissenschaft/seminareinstitute/alte-geschichte/forschung/lykien/arbeitsbereiche/kyaneai/", "url": "https://uni-tuebingen.de/fakultaeten/philosophische-fakultaet/fachbereiche/geschichtswissenschaft/seminareinstitute/alte-geschichte/forschung/lykien/arbeitsbereiche/kyaneai/", "quote": "Auf dem Siedlungshügel fanden sich zwei wohl bronzezeitliche Steinbeile, die dauerhafte Besiedlung allerdings setzte wohl erst um 500 v. Chr. ein.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0145)", "decision": "replace", "status": "MISSING", "reasoning": "The Tübingen Lycia Project, which surveyed Kyaneai, dates the beginning of permanent settlement to about 500 BC (only two stray stone axes are earlier), and the Lycian Way guide dates the start of settlement to the fifth century BC; nothing supports a start around 3000 BC, so the start becomes -500.", "value_page": null}]'::jsonb),
