    ('ad6d3859-ae7c-41cd-9d16-1e13101be9a0'::uuid, 'period_start', '-4000', '-1400', 'fields-wd1-2026-09-26b-s008:ad6d3859-ae7c-41cd-9d16-1e13101be9a0:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''-4000'' -> ''-1400''', '[{"source": "https://www.kilmartin.org/self-guided-trail", "url": "https://www.kilmartin.org/self-guided-trail", "quote": "The Nether Largie Standing Stones were possibly built during the Middle Bronze age 3,000 years ago (1400 – 1050BC) and we do not know why they were built.", "outcome": "found"}, {"source": "https://www.isleofalbion.co.uk/sites/296/nether_largie_stones.php", "url": "https://www.isleofalbion.co.uk/sites/296/nether_largie_stones.php", "quote": "The stones are thought to date to about 1,200BC", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0123)", "decision": "replace", "status": "MISSING", "reasoning": "Kilmartin Museum dates the setting to the Middle Bronze Age, 1400-1050 BC, and Isle of Albion to about 1200 BC; both fall in the 1500-500 BC bucket, so the stored Neolithic 4500-3000 BC start is not supported.", "value_page": null}]'::jsonb),
    ('ad6d3859-ae7c-41cd-9d16-1e13101be9a0'::uuid, 'site_type', 'Megalithic stones', 'Standing stone', 'fields-wd1-2026-09-26b-s008:ad6d3859-ae7c-41cd-9d16-1e13101be9a0:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''Megalithic stones'' -> ''Standing stone''', '[{"source": "https://portal.historicenvironment.scot/apex/f?p=1505:300:::::VIEWTYPE,VIEWREF:designation,SM218", "url": "https://portal.historicenvironment.scot/apex/f?p=1505:300:::::VIEWTYPE,VIEWREF:designation,SM218", "quote": "Prehistoric ritual and funerary: standing stone", "outcome": "found"}, {"source": "https://www.stonepages.com/ancient_scotland/sites/nether.htm", "url": "https://www.stonepages.com/ancient_scotland/sites/nether.htm", "quote": "A group of five standing stones, in a field on the west side of the Kilmartin Burn (Argyll).", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0123)", "decision": "replace", "status": "CONFLICT", "reasoning": "HES schedules the site as standing stones and Stone Pages describes a group of five standing stones; Standing stone is more specific than the generic Megalithic stones.", "value_page": null}]'::jsonb),
    ('ad6d3859-ae7c-41cd-9d16-1e13101be9a0'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Kilmartin_Glen', 'https://nl.wikipedia.org/wiki/Nether_Largie_Standing_Stones', 'fields-wd1-2026-09-26b-s008:ad6d3859-ae7c-41cd-9d16-1e13101be9a0:source_url', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''https://en.wikipedia.org/wiki/Kilmartin_Glen'' -> ''https://nl.wikipedia.org/wiki/Nether_Largie_Standing_Stones''', '[{"source": "https://nl.wikipedia.org/wiki/Nether_Largie_Standing_Stones", "url": "https://nl.wikipedia.org/wiki/Nether_Largie_Standing_Stones", "quote": "De Nether Largie Standing Stones bestaan uit vijf staande stenen, die zijn gerangschikt in een lijn van noordoost naar zuidwest met twee paren met één vrijstaande steen ertussen.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=343", "url": "https://www.megalithic.co.uk/article.php?sid=343", "quote": "The Nether Largie stones are situated some 300m to the southeast of the Temple Wood circles.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0123)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article covers the whole of Kilmartin Glen; the stones have no English article, but Dutch Wikipedia has its own article on the Nether Largie Standing Stones, preferred over a register page.", "value_page": {"lang": "nl", "problem": null, "resolved_title": "Nether Largie Standing Stones", "unreadable": false, "wikibase_item": "Q257435"}}]'::jsonb),
