    ('addf400a-89eb-41a3-8a0e-90d928b7904e'::uuid, 'period_name', '< 4500 BC', '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s008:addf400a-89eb-41a3-8a0e-90d928b7904e:period_name', 'fields-wd1-2026-09-26b-s008 (wd1-derive-period-name): period_start -4000 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-4000) = ''4500 - 3000 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('addf400a-89eb-41a3-8a0e-90d928b7904e'::uuid, 'period_start', '-5000', '-4000', 'fields-wd1-2026-09-26b-s008:addf400a-89eb-41a3-8a0e-90d928b7904e:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''-5000'' -> ''-4000''', '[{"source": "https://heritageuniversityofkerala.com/JournalPDF/Volume8.2/3.pdf", "url": "https://heritageuniversityofkerala.com/JournalPDF/Volume8.2/3.pdf", "quote": "Mundigak as: Period I: 4000 – 3500 B.C", "outcome": "found"}, {"source": "https://www.dafa-afgh.org/mundigak/", "url": "https://www.dafa-afgh.org/mundigak/", "quote": "Les toutes premières occupations du site sont datées du IVe millénaire", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Mundigak", "url": "https://en.wikipedia.org/wiki/Mundigak", "quote": "(~4000–3800 BCE)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0002)", "decision": "replace", "status": "MISSING", "reasoning": "The DAFA (whose mission excavated the site) dates the very first occupation to the 4th millennium, Shaffer''s chronology quoted by Latify and Mahesh puts Period I at 4000-3500 BC, and Wikipedia''s new-research table starts Period I at ~4000 BCE; the start is c. 4000 BC, in the 4500-3000 BC bucket, not before 4500 BC.", "value_page": null}]'::jsonb),
    ('ae56b2a0-b542-4bcb-9364-0448407a5dbf'::uuid, 'site_type', 'Megalithic stones', 'City', 'fields-wd1-2026-09-26b-s008:ae56b2a0-b542-4bcb-9364-0448407a5dbf:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''Megalithic stones'' -> ''City''', '[{"source": "https://en.wikipedia.org/wiki/Cassope", "url": "https://en.wikipedia.org/wiki/Cassope", "quote": "However the city of Kassope was founded in the middle of the 4th century BC", "outcome": "found"}, {"source": "http://odysseus.culture.gr/h/3/eh351.jsp?obj_id=2633", "url": "http://odysseus.culture.gr/h/3/eh351.jsp?obj_id=2633", "quote": "The city flourished in the 3rd century B.C., when the large public buildings were erected and the private houses rebuilt.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0060)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both the Ministry of Culture and English Wikipedia describe Cassope as a city, the capital of the Cassopaeans with a street grid, public buildings and houses; nothing megalithic is described, so ''Megalithic stones'' is replaced by City.", "value_page": null}]'::jsonb),
    ('ae9f040d-018b-40cf-948e-5b95b4604fb5'::uuid, 'period_name', '1 - 500 AD', NULL, 'fields-wd1-2026-09-26b-s008:ae9f040d-018b-40cf-948e-5b95b4604fb5:period_name', 'fields-wd1-2026-09-26b-s008 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('ae9f040d-018b-40cf-948e-5b95b4604fb5'::uuid, 'period_start', '1', NULL, 'fields-wd1-2026-09-26b-s008:ae9f040d-018b-40cf-948e-5b95b4604fb5:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-clear): ''1'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0090)", "decision": "clear", "status": "MISSING", "reasoning": "No two sources date the start of the site: the Roman temple dates after c. AD 286, Ptolemy names Areopolis around AD 150, but the Dead Sea earthquake catalogue says the city appears to have been built by the Nabataeans and records a probably Final Iron Age tower, and DARE gives an undated Hellenistic start; the first occupation is not securely dated, so the field is emptied.", "value_page": null}]'::jsonb),
    ('ae9f040d-018b-40cf-948e-5b95b4604fb5'::uuid, 'site_type', 'Temple complex', 'City', 'fields-wd1-2026-09-26b-s008:ae9f040d-018b-40cf-948e-5b95b4604fb5:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''Temple complex'' -> ''City''', '[{"source": "https://en.wikipedia.org/wiki/Rabba", "url": "https://en.wikipedia.org/wiki/Rabba", "quote": "It was one of the two leading cities of the Karak Plateau at this time.", "outcome": "found"}, {"source": "https://deadseaquake.info/EarthquakeCatalogOfTheDeadSea/Sites/Archaeo/Areopolis.html", "url": "https://deadseaquake.info/EarthquakeCatalogOfTheDeadSea/Sites/Archaeo/Areopolis.html", "quote": "A prominent feature of the Roman urban landscape was the colonnaded street, cleared of its debris for a 30 meter long section by the Department of Antiquities (1962-1963).", "outcome": "found"}, {"source": "https://deadseaquake.info/EarthquakeCatalogOfTheDeadSea/Sites/Archaeo/Areopolis.html", "url": "https://deadseaquake.info/EarthquakeCatalogOfTheDeadSea/Sites/Archaeo/Areopolis.html", "quote": "The city appears to have been built by the Nabataeans (", "outcome": "found"}, {"source": "https://visitkarak.com/place-detail.php?id=2&lang=en", "url": "https://visitkarak.com/place-detail.php?id=2&lang=en", "quote": "The site preserves the remains of stone buildings, architectural columns, public structures, rock-cut reservoirs, and ancient wells that demonstrate sophisticated urban planning and water management. These archaeological remains reflect the city''s importance as a thriving urban settlement throughout different historical periods.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0090)", "decision": "replace", "status": "CONFLICT", "reasoning": "The ruins are those of the Roman and Byzantine city of Areopolis/Rabbathmoba - a colonnaded street, a cistern, a Tetrarchic temple and two churches - which Wikipedia calls one of the two leading cities of the Karak plateau and the Dead Sea catalogue and Visit Karak describe as a city; one temple among street, reservoir and churches is not a temple complex.", "value_page": null}]'::jsonb),
    ('ae9f040d-018b-40cf-948e-5b95b4604fb5'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Rabba', 'https://deadseaquake.info/EarthquakeCatalogOfTheDeadSea/Sites/Archaeo/Areopolis.html', 'fields-wd1-2026-09-26b-s008:ae9f040d-018b-40cf-948e-5b95b4604fb5:source_url', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''https://en.wikipedia.org/wiki/Rabba'' -> ''https://deadseaquake.info/EarthquakeCatalogOfTheDeadSea/Sites/Archaeo/Areopolis.html''', '[{"source": "https://deadseaquake.info/EarthquakeCatalogOfTheDeadSea/Sites/Archaeo/Areopolis.html", "url": "https://deadseaquake.info/EarthquakeCatalogOfTheDeadSea/Sites/Archaeo/Areopolis.html", "quote": "Rabba (Areopolis): plan of the archeological site West [of] the modern road (1999)", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=27243", "url": "https://www.megalithic.co.uk/article.php?sid=27243", "quote": "Qasr Ar-Rabba (today the modern village Al-Rabba) located 12 km north of Al-Karak.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0090)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is about the modern town of Rabba; the Dead Sea earthquake catalogue''s Areopolis page is about the archaeological site itself (plans, colonnaded street, temple, churches), and the Megalithic Portal describes the same ruins at Al-Rabba.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
