    ('aed60d2e-9dec-442b-a7bf-86647aca27b9'::uuid, 'site_type', 'Archaeological site', 'Military', 'fields-wd1-2026-09-26b-s008:aed60d2e-9dec-442b-a7bf-86647aca27b9:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''Archaeological site'' -> ''Military''', '[{"source": "https://en.wikipedia.org/wiki/Battle_at_the_Harzhorn", "url": "https://en.wikipedia.org/wiki/Battle_at_the_Harzhorn", "quote": "The Battle at the Harzhorn took place in the early 3rd century between Germanic and Roman troops near the Harzhorn hill between the towns of Kalefeld and Bad Gandersheim", "outcome": "found"}, {"source": "https://www.spiegel.de/international/germany/major-discovery-archaeologists-find-roman-era-battlefield-in-germany-a-596619.html", "url": "https://www.spiegel.de/international/germany/major-discovery-archaeologists-find-roman-era-battlefield-in-germany-a-596619.html", "quote": "Many of the weapons found are in good condition and they prove that Roman armies were still engaging in major military operations far north of the Alps", "outcome": "found"}, {"source": "https://rom-in-deutschland.de/Seiten/roemerschlacht-am-harzhorn.html", "url": "https://rom-in-deutschland.de/Seiten/roemerschlacht-am-harzhorn.html", "quote": "Dieses antike Schlachtfeld gehört zeitlich zu den Germanien Feldzügen des Kaisers Maximinus Thrax in den Jahren 235/6 n. Chr.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0057)", "decision": "replace", "status": "CONFLICT", "reasoning": "All sources describe the site as a Roman-Germanic battlefield, evidence of Roman military operations; Military is the most specific canonical type for a battlefield, more specific than the stored generic Archaeological site.", "value_page": null}]'::jsonb),
    ('aed60d2e-9dec-442b-a7bf-86647aca27b9'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Location', 'https://en.wikipedia.org/wiki/Battle_at_the_Harzhorn', 'fields-wd1-2026-09-26b-s008:aed60d2e-9dec-442b-a7bf-86647aca27b9:source_url', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''https://en.wikipedia.org/wiki/Location'' -> ''https://en.wikipedia.org/wiki/Battle_at_the_Harzhorn''', '[{"source": "https://en.wikipedia.org/wiki/Battle_at_the_Harzhorn", "url": "https://en.wikipedia.org/wiki/Battle_at_the_Harzhorn", "quote": "The Battle at the Harzhorn took place in the early 3rd century between Germanic and Roman troops near the Harzhorn hill between the towns of Kalefeld and Bad Gandersheim", "outcome": "found"}, {"source": "https://roemerschlachtamharzhorn.de/datierung/", "url": "https://roemerschlachtamharzhorn.de/datierung/", "quote": "dass die Schlacht am Harzhorn mit dieser großangelegten Militäraktion des Maximinus Thrax in Zusammenhang steht", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0057)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is the generic article ''Location''; the English Wikipedia article Battle at the Harzhorn is about this very battlefield near Kalefeld, confirmed by the Landkreis Northeim site project.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Battle at the Harzhorn", "unreadable": false, "wikibase_item": "Q555463"}}]'::jsonb),
