    ('af919ba9-7fa1-4da0-bc15-443767ae8b66'::uuid, 'period_start', '-500', '-80000', 'fields-wd1-2026-09-26b-s008:af919ba9-7fa1-4da0-bc15-443767ae8b66:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''-500'' -> ''-80000''', '[{"source": "https://www.pair-non-pair.fr/en/discover/history-of-the-monument", "url": "https://www.pair-non-pair.fr/en/discover/history-of-the-monument", "quote": "Neanderthals and Homo Sapiens lived here between 80,000 and 18,000 BC.", "outcome": "found"}, {"source": "https://www.gironde-tourisme.com/itineraires/iconiques-a-velo-la-grotte-de-pair-non-pair/", "url": "https://www.gironde-tourisme.com/itineraires/iconiques-a-velo-la-grotte-de-pair-non-pair/", "quote": "bovidés datés de l''Aurignacien (entre 33 000 et 26 000 ans avant Jésus-Christ).", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0054)", "decision": "replace", "status": "MISSING", "reasoning": "The Centre des monuments nationaux, which runs the cave, dates its occupation from 80,000 BC (Mousterian), and Gironde Tourisme dates its engravings to 33,000-26,000 BC; both put the start of the site far before 4500 BC, so the stored 500 BC is replaced by the first occupation, -80000.", "value_page": null}]'::jsonb),
    ('afac29e1-ce20-4266-8f23-7bb05390ac64'::uuid, 'site_type', 'Megalithic structures', 'Road', 'fields-wd1-2026-09-26b-s008:afac29e1-ce20-4266-8f23-7bb05390ac64:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''Megalithic structures'' -> ''Road''', '[{"source": "https://www.labrujulaverde.com/en/2024/04/grotta-di-cocceio-the-first-great-road-tunnel-in-the-world-built-by-the-romans-in-36-bc/", "url": "https://www.labrujulaverde.com/en/2024/04/grotta-di-cocceio-the-first-great-road-tunnel-in-the-world-built-by-the-romans-in-36-bc/", "quote": "Therefore, it is considered the first major Roman road tunnel, and possibly in the world.", "outcome": "found"}, {"source": "https://it.wikipedia.org/wiki/Grotta_di_Cocceio", "url": "https://it.wikipedia.org/wiki/Grotta_di_Cocceio", "quote": "Parallelamente alla galleria carrabile, sul lato settentrionale, correva un acquedotto sotterraneo", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Grotta_di_Cocceio", "url": "https://en.wikipedia.org/wiki/Grotta_di_Cocceio", "quote": "The tunnel was wide enough to allow the passage of two wagons.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0015)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Grotta di Cocceio near Lake Avernus and Cumae is a Roman tunnel cut through Monte Grillo that carried a road wide enough for two wagons, with a separate aqueduct tunnel running parallel; it is a road tunnel, not a megalithic structure.", "value_page": null}]'::jsonb),
