    ('b04ee52d-6549-4877-8131-2475c9989299'::uuid, 'period_start', '1', '-100', 'fields-wd1-2026-09-26b-s008:b04ee52d-6549-4877-8131-2475c9989299:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''1'' -> ''-100''', '[{"source": "https://archeologie.culture.gouv.fr/villa/fr/chiragan-un-domaine-imperial", "url": "https://archeologie.culture.gouv.fr/villa/fr/chiragan-un-domaine-imperial", "quote": "La villa est occupée durant plus de quatre siècles, de la fin du Ier siècle avant notre ère jusqu’au début du Ve siècle.", "outcome": "found"}, {"source": "https://lejournaldugers.fr/article/73598-la-villa-de-chiragan", "url": "https://lejournaldugers.fr/article/73598-la-villa-de-chiragan", "quote": "Cette riche demeure rurale fut fondée au Ier siècle av. JC., sous le règne d''Auguste.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0054)", "decision": "replace", "status": "MISSING", "reasoning": "The French Ministry of Culture''s archaeology site dates the first occupation to the end of the 1st century BC and the Journal du Gers dates the foundation to the 1st century BC under Augustus (the Musée Saint-Raymond''s plan calls the first state Augustan); the start lies in the 500 BC - 1 AD bucket, so the stored 1 is replaced by the first year of the 1st century BC, -100.", "value_page": null}]'::jsonb),
