    ('b0db0a0f-c2c3-4119-bf6f-43f2e040119c'::uuid, 'period_start', '-1000', NULL, 'fields-wd1-2026-09-26b-s008:b0db0a0f-c2c3-4119-bf6f-43f2e040119c:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-clear): ''-1000'' -> None', '[{"source": "WD1 decision (counted, round 1, wd1-r1-b0001)", "decision": "clear", "status": "MISSING", "reasoning": "Every readable source dates Kutlug-Tepe only as a span, never by a first-occupation year: English Wikipedia says a fortification ''dating from the first millennium BC, during the time of the Achaemenid Empire'', and the Quadralectic Architecture page says it was occupied during the Achaemenid reign (558 - 330 BC). The 500 BC bucket boundary falls inside both spans, so no two independent sources place the start in one bucket; the stored -1000 has no attested basis and the field is emptied.", "value_page": null}]'::jsonb),
