    ('b19343e4-3110-4343-8ce8-2f085db85001'::uuid, 'period_name', '3000 - 1500 BC', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s008:b19343e4-3110-4343-8ce8-2f085db85001:period_name', 'fields-wd1-2026-09-26b-s008 (wd1-derive-period-name): period_start -1000 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1000) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('b19343e4-3110-4343-8ce8-2f085db85001'::uuid, 'period_start', '-3000', '-1000', 'fields-wd1-2026-09-26b-s008:b19343e4-3110-4343-8ce8-2f085db85001:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''-3000'' -> ''-1000''', '[{"source": "https://en.wikipedia.org/wiki/Kaunos", "url": "https://en.wikipedia.org/wiki/Kaunos", "quote": "Kaunos was an important sea port, the history of which is supposed to date back to the 10th century BC.", "outcome": "found"}, {"source": "https://mugla.ktb.gov.tr/TR-273368/kaunos.html", "url": "https://mugla.ktb.gov.tr/TR-273368/kaunos.html", "quote": "Arkeolojik belgelere göre dip tarihi MÖ 10. yüzyıla kadar giden Kaunos’un, çok daha eski bir yerleşim yeri olduğu tahmin edilmektedir.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0145)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia and the Muğla culture directorate (Ministry of Culture and Tourism) both date Kaunos''s attested history back to the 10th century BC; nothing places its start in the 3rd-2nd millennium BC, so the start moves to -1000 (bucket 1500 - 500 BC).", "value_page": null}]'::jsonb),
    ('b19343e4-3110-4343-8ce8-2f085db85001'::uuid, 'site_type', 'Temple complex', 'City', 'fields-wd1-2026-09-26b-s008:b19343e4-3110-4343-8ce8-2f085db85001:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''Temple complex'' -> ''City''', '[{"source": "https://en.wikipedia.org/wiki/Kaunos", "url": "https://en.wikipedia.org/wiki/Kaunos", "quote": "was a city of ancient Caria in Anatolia", "outcome": "found"}, {"source": "https://mugla.ktb.gov.tr/TR-273368/kaunos.html", "url": "https://mugla.ktb.gov.tr/TR-273368/kaunos.html", "quote": "Antik dönemde bir liman kenti olan şehir, Dalyan Deltası’nın oluşması nedeniyle bugün deniz kıyısından uzaklaşmıştır.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0145)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both Wikipedia and the Muğla culture directorate describe Kaunos as an ancient (port) city of Caria, not a temple complex; its sanctuaries are parts of the city, so City is the fitting type.", "value_page": null}]'::jsonb),
    ('b1cb10c0-1b83-4b04-90b0-0bc8fdf946fb'::uuid, 'site_type', 'Fortress/citadel', 'Fort', 'fields-wd1-2026-09-26b-s008:b1cb10c0-1b83-4b04-90b0-0bc8fdf946fb:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''Fortress/citadel'' -> ''Fort''', '[{"source": "https://coflein.gov.uk/en/sites/94956", "url": "https://coflein.gov.uk/en/sites/94956", "quote": "Greenala Point Fort is a multivallate promontory fort, naturally defended on the east and south by sandstone cliffs", "outcome": "found"}, {"source": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA135670", "url": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA135670", "quote": "A huge and impressive promontory fort on Greenala Point", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0154)", "decision": "replace", "status": "CONFLICT", "reasoning": "Coflein and the National Trust Heritage Records both describe the site as a promontory fort (a coastal defended enclosure), i.e. a fort rather than a fortress or citadel.", "value_page": null}]'::jsonb),
    ('b1cb10c0-1b83-4b04-90b0-0bc8fdf946fb'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Greenala_Point', 'https://coflein.gov.uk/en/sites/94956', 'fields-wd1-2026-09-26b-s008:b1cb10c0-1b83-4b04-90b0-0bc8fdf946fb:source_url', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''https://en.wikipedia.org/wiki/Greenala_Point'' -> ''https://coflein.gov.uk/en/sites/94956''', '[{"source": "https://coflein.gov.uk/en/sites/94956", "url": "https://coflein.gov.uk/en/sites/94956", "quote": "Greenala Point Fort is a multivallate promontory fort, naturally defended on the east and south by sandstone cliffs", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=24832", "url": "https://www.megalithic.co.uk/article.php?sid=24832", "quote": "Site Name: Greenala Point Fort Alternative Name: Greenala Camp", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0154)", "decision": "replace", "status": "CONFLICT", "reasoning": "The English Wikipedia article Greenala Point is about the headland; the Coflein record NPRN 94956 for Greenala Point Fort (Greenala Camp) is the register entry for the fort itself, and the Megalithic Portal independently names the same Greenala Point Fort.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('b1e7b190-e66c-49da-8df8-2b1345fa68fd'::uuid, 'site_type', 'Temple complex', 'City', 'fields-wd1-2026-09-26b-s008:b1e7b190-e66c-49da-8df8-2b1345fa68fd:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''Temple complex'' -> ''City''', '[{"source": "https://en.wikipedia.org/wiki/Tiwanaku", "url": "https://en.wikipedia.org/wiki/Tiwanaku", "quote": "At its height, the city of Tiwanaku spanned an area of roughly 4 square kilometers (1.5 square miles) and had a population greater than 10,000 individuals.", "outcome": "found"}, {"source": "https://www.worldhistory.org/Tiwanaku/", "url": "https://www.worldhistory.org/Tiwanaku/", "quote": "At an altitude of 3,850 metres (12,600 ft) it was the highest city in the ancient world and had a peak population of between 30,000 and 70,000 residents.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0012)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the World History Encyclopedia describe Tiwanaku as the capital city of the Tiwanaku state, a city of several square kilometres with 10,000 to 70,000 residents; its temples (Akapana, Kalasasaya, Pumapunku) form only its ceremonial core, so City fits the site better than Temple complex.", "value_page": null}]'::jsonb),
    ('b2035589-d46f-496f-9736-15d2251bca4a'::uuid, 'period_name', '500 BC - 1 AD', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s008:b2035589-d46f-496f-9736-15d2251bca4a:period_name', 'fields-wd1-2026-09-26b-s008 (wd1-derive-period-name): period_start -600 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-600) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('b2035589-d46f-496f-9736-15d2251bca4a'::uuid, 'period_start', '-500', '-600', 'fields-wd1-2026-09-26b-s008:b2035589-d46f-496f-9736-15d2251bca4a:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''-500'' -> ''-600''', '[{"source": "https://es.wikipedia.org/wiki/Topoxt%C3%A9", "url": "https://es.wikipedia.org/wiki/Topoxt%C3%A9", "quote": "Período Preclásico Medio (600 a. C. - 1000 d. C.) Aprox", "outcome": "found"}, {"source": "https://www.themayanruinswebsite.com/topoxte.html", "url": "https://www.themayanruinswebsite.com/topoxte.html", "quote": "Topoxte has an early settlement history dating back to the Middle Pre-Classic (700 B.C.-250 A.D.), making it older than Yaxha.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0075)", "decision": "replace", "status": "MISSING", "reasoning": "English Wikipedia says the earliest (late Middle Preclassic) evidence is confined to the Main Plaza on Topoxte Island; Spanish Wikipedia dates the start of construction to the Middle Preclassic, c. 600 BC, and the Mayan Ruins Website to the Middle Pre-Classic from 700 B.C., both in the 1500-500 BC bucket rather than the stored 500 BC - 1 AD, so the start is replaced by -600.", "value_page": null}]'::jsonb),
    ('b2341e58-d5c1-4c9e-8e7a-05a2bc1857f3'::uuid, 'period_name', '3000 - 1500 BC', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s008:b2341e58-d5c1-4c9e-8e7a-05a2bc1857f3:period_name', 'fields-wd1-2026-09-26b-s008 (wd1-derive-period-name): period_start -1250 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1250) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('b2341e58-d5c1-4c9e-8e7a-05a2bc1857f3'::uuid, 'period_start', '-3000', '-1250', 'fields-wd1-2026-09-26b-s008:b2341e58-d5c1-4c9e-8e7a-05a2bc1857f3:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''-3000'' -> ''-1250''', '[{"source": "https://en.wikipedia.org/wiki/South_Lodge_Camp", "url": "https://en.wikipedia.org/wiki/South_Lodge_Camp", "quote": "The site was occupied, according to radiocarbon dating, from about 1250 BC to 1050 BC.", "outcome": "found"}, {"source": "https://salisburymuseum.org.uk/collections/south-lodge-urn/", "url": "https://salisburymuseum.org.uk/collections/south-lodge-urn/", "quote": "Bronze Age, 1200 BC", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0045)", "decision": "replace", "status": "MISSING", "reasoning": "Radiocarbon dates from the 1977-81 re-excavation put the occupation of South Lodge Camp at about 1250-1050 BC (Wikipedia, after the Historic England listing), and the Salisbury Museum dates the urn from the enclosure ditch to 1200 BC. The start therefore falls in the 1500-500 BC bucket, not the stored 3000 BC.", "value_page": null}]'::jsonb),
    ('b2341e58-d5c1-4c9e-8e7a-05a2bc1857f3'::uuid, 'site_type', 'City/town/settlement', 'Settlement', 'fields-wd1-2026-09-26b-s008:b2341e58-d5c1-4c9e-8e7a-05a2bc1857f3:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''City/town/settlement'' -> ''Settlement''', '[{"source": "https://salisburymuseum.org.uk/collections/south-lodge-urn/", "url": "https://salisburymuseum.org.uk/collections/south-lodge-urn/", "quote": "General Pitt-Rivers excavated South Lodge Camp, an enclosed settlement situated on Cranborne Chase in 1893.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/South_Lodge_Camp", "url": "https://en.wikipedia.org/wiki/South_Lodge_Camp", "quote": "Two round timber buildings, and a mound of burnt flint thought to be a cooking area, were found inside the enclosure. Hollows, thought by Pitt Rivers to be natural, were identified as pits for storing grain.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0045)", "decision": "replace", "status": "CONFLICT", "reasoning": "South Lodge Camp is a small Bronze Age enclosed settlement with two roundhouses and grain pits (the Salisbury Museum calls it a dwelling site), with a round barrow cemetery beside it. The camp itself is a farmstead settlement, not a city or town and not the barrows, so Settlement is the specific type.", "value_page": null}]'::jsonb),
    ('b25977e0-0c67-4b01-96e4-d720919676ac'::uuid, 'period_name', '1500 - 500 BC', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s008:b25977e0-0c67-4b01-96e4-d720919676ac:period_name', 'fields-wd1-2026-09-26b-s008 (wd1-derive-period-name): period_start -231 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-231) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('b25977e0-0c67-4b01-96e4-d720919676ac'::uuid, 'period_start', '-1000', '-231', 'fields-wd1-2026-09-26b-s008:b25977e0-0c67-4b01-96e4-d720919676ac:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''-1000'' -> ''-231''', '[{"source": "https://www.enciclopedia.cat/gran-enciclopedia-catalana/akra-leuke", "url": "https://www.enciclopedia.cat/gran-enciclopedia-catalana/akra-leuke", "quote": "Establiment militar fundat per Amílcar Barca l’any 231 aC. És conegut el nom a través de la transcripció grega, que significa ‘el promontori blanc’. De localització incerta, alguns autors l’han volgut identificar amb la ciutat d’Alacant, o amb les ruïnes del tossal de Manises.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Alicante", "url": "https://en.wikipedia.org/wiki/Alicante", "quote": "in the mid-230s BC, which is generally presumed to have been on the site of modern Alicante.", "outcome": "found"}, {"source": "https://www.wikidata.org/wiki/Q11959", "url": "https://www.wikidata.org/wiki/Q11959", "quote": "inception 231 BCE", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0128)", "decision": "replace", "status": "CONFLICT", "reasoning": "Alicante''s attested history begins with Akra Leuke, the fortified settlement Hamilcar Barca founded in 231 BC (Gran Enciclopedia Catalana; Wikipedia: mid-230s BC), presumed to lie at modern Alicante or at the Tossal de Manises, the site of Roman Lucentum. The earlier ''by 1000 BC'' of the Wikipedia article concerns Greek and Phoenician traders on the coast, not this site. 231 BC lies in 500 BC - 1 AD, not in the stored 1500 - 500 BC bucket.", "value_page": null}]'::jsonb),
    ('b25ebe2e-145f-403c-8f6a-e26cdb57050e'::uuid, 'site_type', 'Megalithic structures', 'Villa', 'fields-wd1-2026-09-26b-s008:b25ebe2e-145f-403c-8f6a-e26cdb57050e:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''Megalithic structures'' -> ''Villa''', '[{"source": "https://www.thearchaeologist.org/blog/roman-mosaics-in-cyprus-the-house-of-dionysos-in-paphos", "url": "https://www.thearchaeologist.org/blog/roman-mosaics-in-cyprus-the-house-of-dionysos-in-paphos", "quote": "is a sprawling, 2,000-square-meter Roman villa dating from the late 2nd century CE.", "outcome": "found"}, {"source": "https://de.wikipedia.org/wiki/Arch%C3%A4ologischer_Park_Pafos", "url": "https://de.wikipedia.org/wiki/Arch%C3%A4ologischer_Park_Pafos", "quote": "In der Villa des Dionysos wurden besonders viele gut erhaltene Mosaike in den Jahren 1962 bis 1965 entdeckt", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0019)", "decision": "replace", "status": "CONFLICT", "reasoning": "The House of Dionysos is a Roman mansion with mosaic floors, described as a Roman villa by The Archaeologist and as the Villa des Dionysos by German Wikipedia (the Department of Antiquities calls it a rich Greco-Roman house); nothing megalithic is involved, so the type is Villa.", "value_page": null}]'::jsonb),
    ('b25ebe2e-145f-403c-8f6a-e26cdb57050e'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Paphos_Archaeological_Park', 'https://es.wikipedia.org/wiki/Casa_de_Dioniso_(Pafos)', 'fields-wd1-2026-09-26b-s008:b25ebe2e-145f-403c-8f6a-e26cdb57050e:source_url', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''https://en.wikipedia.org/wiki/Paphos_Archaeological_Park'' -> ''https://es.wikipedia.org/wiki/Casa_de_Dioniso_(Pafos)''', '[{"source": "https://es.wikipedia.org/wiki/Casa_de_Dioniso_(Pafos)", "url": "https://es.wikipedia.org/wiki/Casa_de_Dioniso_(Pafos)", "quote": "La Casa de Dioniso es el nombre que se le da a una vivienda privada de la época", "outcome": "found"}, {"source": "https://www.culture.gov.cy/dmculture/DA/DA.nsf/All/59FFC9310818070EC225719B003A2EB8?OpenDocument", "url": "https://www.culture.gov.cy/dmculture/DA/DA.nsf/All/59FFC9310818070EC225719B003A2EB8?OpenDocument", "quote": "The House of Dionysus occupies 2000sq. metres of which 556 are covered with mosaic floors decorated with mythological, vintage and hunting scenes.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0019)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL redirects to the article on the whole of Nea Paphos; the house has no English article, but Spanish Wikipedia''s ''Casa de Dioniso (Pafos)'' is devoted to this very house, which the Department of Antiquities independently describes as the House of Dionysus.", "value_page": {"lang": "es", "problem": null, "resolved_title": "Casa de Dioniso (Pafos)", "unreadable": false, "wikibase_item": "Q53556398"}}]'::jsonb),
    ('b2a97f1e-1f85-4f7f-97d0-38da53be836a'::uuid, 'period_name', '4500 - 3000 BC', NULL, 'fields-wd1-2026-09-26b-s008:b2a97f1e-1f85-4f7f-97d0-38da53be836a:period_name', 'fields-wd1-2026-09-26b-s008 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('b2a97f1e-1f85-4f7f-97d0-38da53be836a'::uuid, 'period_start', '-4000', NULL, 'fields-wd1-2026-09-26b-s008:b2a97f1e-1f85-4f7f-97d0-38da53be836a:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-clear): ''-4000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0083)", "decision": "clear", "status": "MISSING", "reasoning": "Heritage Ireland and the Dublin Mountains Partnership call it a Bronze Age cairn (possibly a reused Neolithic monument), but no source found gives a year, century or millennium for its construction, so the stored -4000 cannot be sourced.", "value_page": null}]'::jsonb),
    ('b2a97f1e-1f85-4f7f-97d0-38da53be836a'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Tibradden_Mountain', 'https://de.wikipedia.org/wiki/Tibradden_Cairn', 'fields-wd1-2026-09-26b-s008:b2a97f1e-1f85-4f7f-97d0-38da53be836a:source_url', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''https://en.wikipedia.org/wiki/Tibradden_Mountain'' -> ''https://de.wikipedia.org/wiki/Tibradden_Cairn''', '[{"source": "https://de.wikipedia.org/wiki/Tibradden_Cairn", "url": "https://de.wikipedia.org/wiki/Tibradden_Cairn", "quote": "Der Tibradden Cairn (auch Bradden''s Grave genannt) ist ein prähistorischer Cairn", "outcome": "found"}, {"source": "https://heritageireland.ie/unguided-sites/tibradden-cairn/", "url": "https://heritageireland.ie/unguided-sites/tibradden-cairn/", "quote": "Tibradden Cairn is a National Monument in state guardianship", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0083)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is about the mountain the cairn stands on; the cairn has its own article only in German Wikipedia (Tibradden Cairn), which Heritage Ireland''s page on the same national monument confirms by name.", "value_page": {"lang": "de", "problem": null, "resolved_title": "Tibradden Cairn", "unreadable": false, "wikibase_item": "Q15850896"}}]'::jsonb),
    ('b2db3feb-e9a8-490b-a0ec-f0549f17d389'::uuid, 'period_name', '1 - 500 AD', NULL, 'fields-wd1-2026-09-26b-s008:b2db3feb-e9a8-490b-a0ec-f0549f17d389:period_name', 'fields-wd1-2026-09-26b-s008 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('b2db3feb-e9a8-490b-a0ec-f0549f17d389'::uuid, 'period_start', '1', NULL, 'fields-wd1-2026-09-26b-s008:b2db3feb-e9a8-490b-a0ec-f0549f17d389:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-clear): ''1'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0074)", "decision": "clear", "status": "MISSING", "reasoning": "English Wikipedia dates the site to the second half of the 4th century AD (after Fialko 2000). The excavators (Garrison et al. 2016, Journal of Field Archaeology) instead place its establishment as a sacred hilltop site in the Late Preclassic (400 BC-AD 250), a range that spans two buckets. Their abstract is not readable by plain GET, and no two independent readable sources agree on a start date.", "value_page": null}]'::jsonb),
    ('b2db3feb-e9a8-490b-a0ec-f0549f17d389'::uuid, 'site_type', 'City/town/settlement', NULL, 'fields-wd1-2026-09-26b-s008:b2db3feb-e9a8-490b-a0ec-f0549f17d389:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-clear): ''City/town/settlement'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0074)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia calls Bejucal only a Maya archaeological site subordinate to El Zotz. The excavators call it a minor Maya center that became a royal country house (Journal of Field Archaeology 2016, not readable by plain GET), and only USA Today''s report of that study calls it a palace complex. No two independent readable sources say what kind of site it is, so the unsupported City/town/settlement is emptied.", "value_page": null}]'::jsonb),
    ('b2e10c58-6558-4472-93c5-c167a7d17ee7'::uuid, 'period_name', '4500 - 3000 BC', NULL, 'fields-wd1-2026-09-26b-s008:b2e10c58-6558-4472-93c5-c167a7d17ee7:period_name', 'fields-wd1-2026-09-26b-s008 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('b2e10c58-6558-4472-93c5-c167a7d17ee7'::uuid, 'period_start', '-4500', NULL, 'fields-wd1-2026-09-26b-s008:b2e10c58-6558-4472-93c5-c167a7d17ee7:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-clear): ''-4500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0048)", "decision": "clear", "status": "MISSING", "reasoning": "The village''s history (Domesday 1085) is not the site''s, and the barrow the entry stands for cannot be identified among the several scheduled barrows of the parish, which are dated variously ''Bronze Age'' (Wambarrows) and ''Neolithic to Bronze Age''. No source dates this site, so the field is cleared.", "value_page": null}]'::jsonb),
    ('b2e10c58-6558-4472-93c5-c167a7d17ee7'::uuid, 'site_type', 'Barrow', NULL, 'fields-wd1-2026-09-26b-s008:b2e10c58-6558-4472-93c5-c167a7d17ee7:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-clear): ''Barrow'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0048)", "decision": "clear", "status": "CONFLICT", "reasoning": "The sources about Winsford, Somerset describe a village and civil parish; the stored Barrow refers to an unidentified monument in the parish, and the parish holds barrows, a hillfort (Road Castle), enclosures and an inscribed stone (the Caratacus Stone). No two sources describe this entry itself, so the field is cleared until the owner fixes its identity.", "value_page": null}]'::jsonb),
    ('b2e10c58-6558-4472-93c5-c167a7d17ee7'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Winsford,_Somerset', NULL, 'fields-wd1-2026-09-26b-s008:b2e10c58-6558-4472-93c5-c167a7d17ee7:source_url', 'fields-wd1-2026-09-26b-s008 (wd1-clear): ''https://en.wikipedia.org/wiki/Winsford,_Somerset'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0048)", "decision": "clear", "status": "CONFLICT", "reasoning": "The stored page is the Wikipedia article on the village and civil parish in which the monument lies, not on the monument. Because the entry cannot be tied to one of the parish''s barrows, no page about this very site can be named, so the field is cleared.", "value_page": null}]'::jsonb),
    ('b306540a-ea4d-4cd9-8ad1-04a57629f65b'::uuid, 'period_name', '1000 - 1500 AD', NULL, 'fields-wd1-2026-09-26b-s008:b306540a-ea4d-4cd9-8ad1-04a57629f65b:period_name', 'fields-wd1-2026-09-26b-s008 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('b306540a-ea4d-4cd9-8ad1-04a57629f65b'::uuid, 'period_start', '1000', NULL, 'fields-wd1-2026-09-26b-s008:b306540a-ea4d-4cd9-8ad1-04a57629f65b:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-clear): ''1000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0110)", "decision": "clear", "status": "MISSING", "reasoning": "The Ministry of Culture''s declaration file assigns the complex only to the Inca Late Horizon (Horizonte Tardio), and the tourism and encyclopedia pages call it Inca without a year or century. No two sources give a dated start, so the field is cleared.", "value_page": null}]'::jsonb),
    ('b306540a-ea4d-4cd9-8ad1-04a57629f65b'::uuid, 'site_type', 'Polygonal masonry', 'Palace', 'fields-wd1-2026-09-26b-s008:b306540a-ea4d-4cd9-8ad1-04a57629f65b:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''Polygonal masonry'' -> ''Palace''', '[{"source": "https://www.saexpeditions.com/blog/post/vilcashuaman-an-inca-experience-like-no-other", "url": "https://www.saexpeditions.com/blog/post/vilcashuaman-an-inca-experience-like-no-other", "quote": "as well as a palace, a temple, a defensive tower, and an Inca stone bath", "outcome": "found"}, {"source": "https://www.turismoperuano.com/complejo-arqueologico-de-pumacocha-o-intiwatana-ayacucho", "url": "https://www.turismoperuano.com/complejo-arqueologico-de-pumacocha-o-intiwatana-ayacucho", "quote": "Según algunos investigadores, este sitio habría sido considerado como una zona residencial y de descanso del élite Inca, pues entre las construcciones destacan el palacio consta de una construcción bien acabada", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0019)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Intihuatana (Pumacocha) complex near Vischongo in Ayacucho is described by a tour operator as an Inca elite retreat with a palace, temple, tower, sundial and stone bath, and by Peru''s tourism-resource inventory (Turismo Peruano) as a residential and rest area of the Inca elite whose outstanding building is the finely built palace; neither source describes it as polygonal masonry (only the bath has one 13-angled stone), so Palace is the most specific canonical type.", "value_page": null}]'::jsonb),
    ('b306aff1-60d0-4d34-85e3-fe206911dc65'::uuid, 'period_name', '1500 - 500 BC', NULL, 'fields-wd1-2026-09-26b-s008:b306aff1-60d0-4d34-85e3-fe206911dc65:period_name', 'fields-wd1-2026-09-26b-s008 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('b306aff1-60d0-4d34-85e3-fe206911dc65'::uuid, 'period_start', '-1500', NULL, 'fields-wd1-2026-09-26b-s008:b306aff1-60d0-4d34-85e3-fe206911dc65:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-clear): ''-1500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0045)", "decision": "clear", "status": "MISSING", "reasoning": "The sources call it Iron Age, from pottery found on the summit (one sherd possibly Late Bronze Age), but none dates its construction or first occupation to a year or century. The Dorset HER''s ''800 BC to 42 AD'' is only the standard span of the Iron Age period term, and no second source gives a date, so the stored -1500 cannot be kept.", "value_page": null}]'::jsonb),
    ('b306aff1-60d0-4d34-85e3-fe206911dc65'::uuid, 'site_type', 'City/town/settlement', 'Fort', 'fields-wd1-2026-09-26b-s008:b306aff1-60d0-4d34-85e3-fe206911dc65:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''City/town/settlement'' -> ''Fort''', '[{"source": "https://wikishire.co.uk/wiki/Shipton_Hill", "url": "https://wikishire.co.uk/wiki/Shipton_Hill", "quote": "The hill''s summit is ringed by the earthworks of an Iron Age hill fort, and crowned today with a trig point.", "outcome": "found"}, {"source": "https://heritage.dorsetcouncil.gov.uk/Monument/MDO2432", "url": "https://heritage.dorsetcouncil.gov.uk/Monument/MDO2432", "quote": "Possibly an unfinished hillfort.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0045)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Dorset HER records the Shipton Hill earthwork as a hillfort (Iron Age), Wikishire and the Megalithic Portal call it an Iron Age hill fort, and Wikidata has it as a contour fort. Historic England''s ''defended settlement'' is also a banked defended enclosure, so Fort fits better than the generic City/town/settlement.", "value_page": null}]'::jsonb),
    ('b3ad3302-103a-4bbe-83a5-0f27d63ea8f4'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/La_Blanca', 'https://en.wikipedia.org/wiki/La_Blanca,_San_Marcos_(archaeological_site)', 'fields-wd1-2026-09-26b-s008:b3ad3302-103a-4bbe-83a5-0f27d63ea8f4:source_url', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''https://en.wikipedia.org/wiki/La_Blanca'' -> ''https://en.wikipedia.org/wiki/La_Blanca,_San_Marcos_(archaeological_site)''', '[{"source": "https://en.wikipedia.org/wiki/La_Blanca,_San_Marcos_(archaeological_site)", "url": "https://en.wikipedia.org/wiki/La_Blanca,_San_Marcos_(archaeological_site)", "quote": "La Blanca is a pre-Columbian Mesoamerican archaeological site in present-day La Blanca", "outcome": "found"}, {"source": "https://culturaguate.gob.gt/76-figurillas-de-ceramica-de-la-blanca/", "url": "https://culturaguate.gob.gt/76-figurillas-de-ceramica-de-la-blanca/", "quote": "Al inicio del Preclásico Medio, el sitio arqueológico La Blanca, en San Marcos, dominó esta importante área", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0012)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is the disambiguation page La Blanca; the site in San Marcos, Guatemala (14.595N 92.139W, matching the stored point) has its own English Wikipedia article, and the Guatemalan Ministry of Culture independently names the archaeological site La Blanca in San Marcos.", "value_page": {"lang": "en", "problem": null, "resolved_title": "La Blanca, San Marcos (archaeological site)", "unreadable": false, "wikibase_item": "Q3820666"}}]'::jsonb),
    ('b3d37445-fbc6-479b-8f04-d4cbf95f2292'::uuid, 'period_name', '1500 - 500 BC', NULL, 'fields-wd1-2026-09-26b-s008:b3d37445-fbc6-479b-8f04-d4cbf95f2292:period_name', 'fields-wd1-2026-09-26b-s008 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('b3d37445-fbc6-479b-8f04-d4cbf95f2292'::uuid, 'period_start', '-1500', NULL, 'fields-wd1-2026-09-26b-s008:b3d37445-fbc6-479b-8f04-d4cbf95f2292:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-clear): ''-1500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0134)", "decision": "clear", "status": "MISSING", "reasoning": "The Castilla-La Mancha heritage catalogue places the first known settlement on the Cerro del Bú across the river (a separate Bronze Age site) and only undated Late Bronze Age finds inside the city itself, while written history starts with the Carpetanian city already existing at the Roman conquest of 193 BC; no two sources give a year or century for the start of occupation of the city''s own hill, so the field is emptied.", "value_page": null}]'::jsonb),
    ('b40d492a-193f-422b-bd42-559624dd2079'::uuid, 'period_name', '1500 - 500 BC', '500 - 1000 AD', 'fields-wd1-2026-09-26b-s008:b40d492a-193f-422b-bd42-559624dd2079:period_name', 'fields-wd1-2026-09-26b-s008 (wd1-derive-period-name): period_start 550 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(550) = ''500 - 1000 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('b40d492a-193f-422b-bd42-559624dd2079'::uuid, 'period_start', '-1500', '550', 'fields-wd1-2026-09-26b-s008:b40d492a-193f-422b-bd42-559624dd2079:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''-1500'' -> ''550''', '[{"source": "https://www.jalkipeli.net/virnamaen-muinaisjaannosalue-on-kaupunkiretkeilijalle-mielenkiintoinen-kohde/", "url": "https://www.jalkipeli.net/virnamaen-muinaisjaannosalue-on-kaupunkiretkeilijalle-mielenkiintoinen-kohde/", "quote": "Virnamäen muinaisjäännösalue edustaa Aurajokilaakson nuoremman rautakauden (550-1150 jKr.) aikaisia muinaisjäännöksiä.", "outcome": "found"}, {"source": "https://www.turkulaiset.fi/virnamaki.html", "url": "https://www.turkulaiset.fi/virnamaki.html", "quote": "Virnamäen muinaisjäännösalue ympäristöineen on merkittävä nuoremman rautakauden (550 - 1150 jKr) löytöjen keskittymä.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0050)", "decision": "replace", "status": "MISSING", "reasoning": "Both pages date the Virnamäki remains (cremation cemetery, dwelling site, cup stones) to the Younger Iron Age, 550-1150 AD, and Wikipedia and the heritage register call the area Iron Age; the stored -1500 (Bronze Age) is wrong and the start belongs in the 500 - 1000 AD bucket.", "value_page": null}]'::jsonb),
    ('b40d492a-193f-422b-bd42-559624dd2079'::uuid, 'site_type', 'Monument', 'Cemetery', 'fields-wd1-2026-09-26b-s008:b40d492a-193f-422b-bd42-559624dd2079:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''Monument'' -> ''Cemetery''', '[{"source": "https://en.wikipedia.org/wiki/Virnam%C3%A4ki", "url": "https://en.wikipedia.org/wiki/Virnam%C3%A4ki", "quote": "In addition to having been a dwelling site, the area is also known for its cremation cemeteries under level ground and also multiple stones with cup marks.", "outcome": "found"}, {"source": "https://www.turkulaiset.fi/virnamaki.html", "url": "https://www.turkulaiset.fi/virnamaki.html", "quote": "Virnamäen kalmisto ja asuinpaikka, sen lähistöllä sijaitsevat kuppikivet ja joen rannassa olevat Komosten (hauta)kummut ovat muinaismuistolailla suojeltuja.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0050)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored point is the register''s Virnamäki 1, an Iron Age cremation cemetery with a dwelling site; Wikipedia and turkulaiset.fi both name the cemetery (kalmisto) as the site''s core, with the cup-marked stones lying nearby, so Cemetery is more specific than Monument.", "value_page": null}]'::jsonb),
    ('b43e7f32-5f59-4370-9cf0-43c3f159e4e3'::uuid, 'period_name', '1 - 500 AD', NULL, 'fields-wd1-2026-09-26b-s008:b43e7f32-5f59-4370-9cf0-43c3f159e4e3:period_name', 'fields-wd1-2026-09-26b-s008 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('b43e7f32-5f59-4370-9cf0-43c3f159e4e3'::uuid, 'period_start', '1', NULL, 'fields-wd1-2026-09-26b-s008:b43e7f32-5f59-4370-9cf0-43c3f159e4e3:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-clear): ''1'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0075)", "decision": "clear", "status": "MISSING", "reasoning": "The excavators (Suyuc et al. 2005) and Wikipedia date La Muerta only to the Early and Late Classic by ceramics, with no year, century or millennium, so no two sources give a dated start and the stored AD 1 is emptied.", "value_page": null}]'::jsonb),
    ('b43e7f32-5f59-4370-9cf0-43c3f159e4e3'::uuid, 'site_type', 'Temple complex', 'Settlement', 'fields-wd1-2026-09-26b-s008:b43e7f32-5f59-4370-9cf0-43c3f159e4e3:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''Temple complex'' -> ''Settlement''', '[{"source": "https://docslib.org/doc/10152419/excavations-at-the-site-of-la-muerta-mirador-basin-peten", "url": "https://docslib.org/doc/10152419/excavations-at-the-site-of-la-muerta-mirador-basin-peten", "quote": "When referring to more specific features in the description of this settlement, it was said that the mapping revealed two major architectural areas with 11 residential groups.", "outcome": "found"}, {"source": "https://www.asociaciontikal.com/simposio-18-ano-2004/07-suyuc-y-balcarcel-04-doc/", "url": "https://www.asociaciontikal.com/simposio-18-ano-2004/07-suyuc-y-balcarcel-04-doc/", "quote": "La Muerta se identificó como un centro habitado durante el Clásico Tardío.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/La_Muerta", "url": "https://en.wikipedia.org/wiki/La_Muerta", "quote": "Eleven residential areas have been identified within these two groups.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0012)", "decision": "replace", "status": "MISSING", "reasoning": "The excavation report by Suyuc et al. (English text on docslib, Spanish original at Asociacion Tikal) calls La Muerta a settlement identified as an inhabited centre of the Late Classic with 11 residential groups, and English Wikipedia likewise records eleven residential areas; only one building (A1) is a temple, so Temple complex does not describe the site.", "value_page": null}]'::jsonb),
    ('b4fb0095-3513-4b44-a48b-22c539b1a914'::uuid, 'site_type', 'Megalithic structures', 'Monument', 'fields-wd1-2026-09-26b-s008:b4fb0095-3513-4b44-a48b-22c539b1a914:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''Megalithic structures'' -> ''Monument''', '[{"source": "https://researchportal.unamur.be/en/projects/the-kiosk-of-taharqa-in-the-temple-of-amun-in-karnak-epigraphic-p/", "url": "https://researchportal.unamur.be/en/projects/the-kiosk-of-taharqa-in-the-temple-of-amun-in-karnak-epigraphic-p/", "quote": "The kiosk of Taharqa is one of the major monuments of the archaeological site of Karnak in Egypt.", "outcome": "found"}, {"source": "https://digitalkarnak.ucsc.edu/taharqo-kiosk/", "url": "https://digitalkarnak.ucsc.edu/taharqo-kiosk/", "quote": "Two rows of five large open papyrus form columns, connected by low screen walls, formed the free-standing structure.", "outcome": "found"}, {"source": "https://digitalkarnak.ucsc.edu/taharqo-kiosk/", "url": "https://digitalkarnak.ucsc.edu/taharqo-kiosk/", "quote": "Only one column now stands complete today.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0022)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is the single surviving 21 m papyrus column of Taharqa''s free-standing kiosk in the first court of the Amun temple, which the University of Namur calls one of the major monuments of Karnak; it is a built monument, not a megalithic structure, and no canonical type names a column, so Monument is the most specific fit.", "value_page": null}]'::jsonb),
    ('b4fb0095-3513-4b44-a48b-22c539b1a914'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Precinct_of_Amun-Re', 'https://digitalkarnak.ucsc.edu/taharqo-kiosk/', 'fields-wd1-2026-09-26b-s008:b4fb0095-3513-4b44-a48b-22c539b1a914:source_url', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''https://en.wikipedia.org/wiki/Precinct_of_Amun-Re'' -> ''https://digitalkarnak.ucsc.edu/taharqo-kiosk/''', '[{"source": "https://digitalkarnak.ucsc.edu/taharqo-kiosk/", "url": "https://digitalkarnak.ucsc.edu/taharqo-kiosk/", "quote": "The Taharqo kiosk was located in the first court of the temple.", "outcome": "found"}, {"source": "https://digitalkarnak.ucsc.edu/taharqo-kiosk/", "url": "https://digitalkarnak.ucsc.edu/taharqo-kiosk/", "quote": "Only one column now stands complete today.", "outcome": "found"}, {"source": "https://researchportal.unamur.be/en/projects/the-kiosk-of-taharqa-in-the-temple-of-amun-in-karnak-epigraphic-p/", "url": "https://researchportal.unamur.be/en/projects/the-kiosk-of-taharqa-in-the-temple-of-amun-in-karnak-epigraphic-p/", "quote": "The kiosk of Taharqa is one of the major monuments of the archaeological site of Karnak in Egypt.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0022)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored article is about the whole Precinct of Amun-Re and the column has no Wikipedia article; UCSC''s Digital Karnak page on the Taharqo kiosk covers the monument whose only complete standing column this is, and the University of Namur''s kiosk project names the same kiosk of Taharqa at Karnak.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
