    ('b51b2f98-a99a-4742-ac2a-28df400dae47'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Villar_de_Domingo_Garc%C3%ADa', 'https://es.wikipedia.org/wiki/Villa_romana_de_Noheda', 'fields-wd1-2026-09-26b-s008:b51b2f98-a99a-4742-ac2a-28df400dae47:source_url', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''https://en.wikipedia.org/wiki/Villar_de_Domingo_Garc%C3%ADa'' -> ''https://es.wikipedia.org/wiki/Villa_romana_de_Noheda''', '[{"source": "https://es.wikipedia.org/wiki/Villa_romana_de_Noheda", "url": "https://es.wikipedia.org/wiki/Villa_romana_de_Noheda", "quote": "La villa romana de Noheda es un yacimiento arqueológico localizado junto a la localidad española de Noheda", "outcome": "found"}, {"source": "https://es.wikipedia.org/wiki/Villa_romana_de_Noheda", "url": "https://es.wikipedia.org/wiki/Villa_romana_de_Noheda", "quote": "en el término municipal de Villar de Domingo García", "outcome": "found"}, {"source": "https://cultura.castillalamancha.es/patrimonio/yacimientos-visitables/villa-romana-de-noheda", "url": "https://cultura.castillalamancha.es/patrimonio/yacimientos-visitables/villa-romana-de-noheda", "quote": "Se localiza a escasos 500 metros al noroeste de la pedanía de Noheda, de la cual toma su nombre, perteneciente al municipio conquense de Villar de Domingo García", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0135)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is about the municipality of Villar de Domingo García; the Roman villa in it (Noheda) has no English article, so its own Spanish Wikipedia article ''Villa romana de Noheda'', which places it in the municipality of Villar de Domingo García, replaces it; the regional heritage service''s page names the same villa and municipality.", "value_page": {"lang": "es", "problem": null, "resolved_title": "Villa romana de Noheda", "unreadable": false, "wikibase_item": "Q6162509"}}]'::jsonb),
