    ('b9609879-342b-4fae-8dd5-5f6a6ac155d1'::uuid, 'site_type', 'City/town/settlement', 'Settlement', 'fields-wd1-2026-09-26b-s008:b9609879-342b-4fae-8dd5-5f6a6ac155d1:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''City/town/settlement'' -> ''Settlement''', '[{"source": "https://en.wikipedia.org/wiki/Na_Nova", "url": "https://en.wikipedia.org/wiki/Na_Nova", "quote": "is a Spanish Iron Age Talaiotic settlement located on the island of Mallorca", "outcome": "found"}, {"source": "https://www.lausa.cat/projectes/na-nova", "url": "https://www.lausa.cat/projectes/na-nova", "quote": "es tracta d’un poblat talaiòtic de l’Edat del Ferro", "outcome": "found"}, {"source": "https://ajsantanyi.net/en/node/6741", "url": "https://ajsantanyi.net/en/node/6741", "quote": "que és un dels nombrosos poblats de l’Edat del Bronze que hi ha a Mallorca.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0132)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia, the excavating association Lausa and the Santanyí town council all describe Na Nova as a prehistoric settlement (poblat) whose main building is a talaiot, with the village rooms around it. Settlement is the specific type for the site as a whole, rather than the combined City/town/settlement.", "value_page": null}]'::jsonb),
