    ('ba74c51b-0b28-4e93-aadb-7da862f574da'::uuid, 'period_start', '-500', '-3800', 'fields-wd1-2026-09-26b-s008:ba74c51b-0b28-4e93-aadb-7da862f574da:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''-500'' -> ''-3800''', '[{"source": "https://en.wikipedia.org/wiki/Yeronisos", "url": "https://en.wikipedia.org/wiki/Yeronisos", "quote": "The excavations have established three periods of occupation on Yeronisos. Early Chalcolithic (3800 BC), late Hellenistic (80-30 BC), and Byzantine (6th-7th century and 13th century).", "outcome": "found"}, {"source": "https://www.culture.gov.cy/dmculture/DA/DA.nsf/All/2EC1767270AED8F9422577AE0048AAD5/$file/PRESS%20RELEASE%202011%20english.pdf", "url": "https://www.culture.gov.cy/dmculture/DA/DA.nsf/All/2EC1767270AED8F9422577AE0048AAD5/$file/PRESS%20RELEASE%202011%20english.pdf", "quote": "A deposit of stone tools, a female figurine, and a bead was deliberately placed on Geronisos in a pit with ash during the early Chalcolithic period, around 3800 B.C.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0021)", "decision": "replace", "status": "MISSING", "reasoning": "English Wikipedia and the Cyprus Department of Antiquities'' 2011 press release on the NYU excavations both date the first occupation of Yeronisos (Geronisos) to the Early Chalcolithic, around 3800 BC, before the late Hellenistic sanctuary; the start therefore lies in 4500 - 3000 BC, not in the stored 500 BC - 1 AD bucket.", "value_page": null}]'::jsonb),
