    ('bdd568d3-3a54-442a-9f8c-af7ac07bbaf0'::uuid, 'site_type', 'Infrastructure', 'Cave Structures', 'fields-wd1-2026-09-26b-s008:bdd568d3-3a54-442a-9f8c-af7ac07bbaf0:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''Infrastructure'' -> ''Cave Structures''', '[{"source": "https://www.aubreyresearch.com/uk/monuments/fogou-70m-north-of-pendeen-manor-farm-1004295", "url": "https://www.aubreyresearch.com/uk/monuments/fogou-70m-north-of-pendeen-manor-farm-1004295", "quote": "Fogou 70m north of Pendeen Manor Farm is a prehistoric underground stone-built structure located in Cornwall.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=4130", "url": "https://www.megalithic.co.uk/article.php?sid=4130", "quote": "Site Name: Pendeen Fogou Alternative Name: Pendeen Vau Country: England County: Cornwall Type: Souterrain (Fogou, Earth House)", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Pendeen_Vau", "url": "https://en.wikipedia.org/wiki/Pendeen_Vau", "quote": "Pendeen Vau is a fogou on the Cornish coast of England", "outcome": "found"}, {"source": "http://www.megalithics.com/england/pendeen/pendmain.htm", "url": "http://www.megalithics.com/england/pendeen/pendmain.htm", "quote": "The word fogou is dervied from the Cornish for \"cave\"", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0043)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia, the Megalithic Portal, megalithics.com and the scheduled-monument record all describe the site as a fogou, an underground stone-built souterrain passage (the word is Cornish for ''cave''); that is an artificial underground structure, not infrastructure, so Cave Structures is the fitting type.", "value_page": null}]'::jsonb),
    ('bdd92d68-2715-4dfe-a956-e2f3a5b77465'::uuid, 'site_type', 'Pyramid complex', 'City', 'fields-wd1-2026-09-26b-s008:bdd92d68-2715-4dfe-a956-e2f3a5b77465:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''Pyramid complex'' -> ''City''', '[{"source": "https://en.wikipedia.org/wiki/La_Milpa", "url": "https://en.wikipedia.org/wiki/La_Milpa", "quote": "La Milpa is an archaeological site and an ancient Maya city within the Three River region of Northwest Belize bordering Mexico and Guatemala.", "outcome": "found"}, {"source": "https://www.bu.edu/lamilpa/LM_saa99/LaMilpa.html", "url": "https://www.bu.edu/lamilpa/LM_saa99/LaMilpa.html", "quote": "LaMAP is an interdisciplinary, multi-institutional investigation of an ancient Maya city in Belize, based at Boston University and co-directed by Professor Norman Hammond and Dr. Gair Tourtellot.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0011)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the excavators (Boston University''s LaMAP) both describe La Milpa as an ancient Maya city, the third largest site in Belize with plazas, courtyards and settlement over 6 km; its temple-pyramids are part of that city, so City is the most specific fitting type rather than Pyramid complex.", "value_page": null}]'::jsonb),
    ('beb7f985-afb1-48b4-a77c-daffe463deba'::uuid, 'geom', '0101000020E6100000187F108EB13914407E281DB48D604240', 'SRID=4326;POINT(5.08433 36.75587)', 'fields-wd1-2026-09-26b-s008:beb7f985-afb1-48b4-a77c-daffe463deba:geom', 'fields-wd1-2026-09-26b-s008 (wd1-point): 36.754324449765576, 5.0563413808411255 -> 36.75587, 5.08433', '[{"source": "https://www.geonames.org/2505329", "url": "https://www.geonames.org/2505329", "quote": "Coordinates 36.75587, 5.08433", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/4085381690", "url": "https://www.openstreetmap.org/node/4085381690", "quote": "36.7570052, 5.0834379", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0004)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Princeton Encyclopedia places ancient Saldae on the slopes of Mount Gouraya, on the Moussa and Bridja spurs of the old town of Béjaïa, with Roman cisterns still visible in the upper town. GeoNames puts Béjaïa at 36.75587, 5.08433 (at Bordj Moussa, on that spur), and OpenStreetMap maps the Roman cisterns 130 m away. The stored point lies about 2.5 km west in the modern suburbs, and the rough gazetteer points (Wikipedia 36.75, 5.0667; DARE 36.7415, 5.0581) fall there too, so the point moves to the old town.", "value_page": null}]'::jsonb),
