    ('beb7f985-afb1-48b4-a77c-daffe463deba'::uuid, 'period_name', '1 - 500 AD', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s008:beb7f985-afb1-48b4-a77c-daffe463deba:period_name', 'fields-wd1-2026-09-26b-s008 (wd1-derive-period-name): period_start -400 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-400) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('beb7f985-afb1-48b4-a77c-daffe463deba'::uuid, 'period_start', '1', '-400', 'fields-wd1-2026-09-26b-s008:beb7f985-afb1-48b4-a77c-daffe463deba:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''1'' -> ''-400''', '[{"source": "https://fr.wikipedia.org/wiki/Saldae", "url": "https://fr.wikipedia.org/wiki/Saldae", "quote": "L''existence d''une ville sur le site de Saldae est prouvée dès le milieu du IVe siècle av. J.-C", "outcome": "found"}, {"source": "https://journals.openedition.org/encyclopedieberbere/4127?lang=fr", "url": "https://journals.openedition.org/encyclopedieberbere/4127?lang=fr", "quote": "La ville fut entraînée dans la seconde guerre punique (218-201 avant J.-C.).", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0004)", "decision": "replace", "status": "MISSING", "reasoning": "French Wikipedia and the Encyclopédie berbère (J.-P. Laporte) both cite the Periplus of Pseudo-Scylax (before 360 BC) as the first record of the town, which was partly Punicised before the mid-4th century BC; the Encyclopédie berbère then follows the Punic town through the Second Punic War (218-201 BC) to the Augustan colony (27-26 BC). The start is the 4th century BC (-400), not the stored AD 1.", "value_page": null}]'::jsonb),
