    ('bebaa4d3-fb8e-46a4-b9cb-fe6589925889'::uuid, 'period_start', '-1000', NULL, 'fields-wd1-2026-09-26b-s008:bebaa4d3-fb8e-46a4-b9cb-fe6589925889:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-clear): ''-1000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0079)", "decision": "clear", "status": "MISSING", "reasoning": "No source dates this stone grave: the Megalithic Portal gives only the period label ''Neolithic and Bronze Age'' and the Pagar Alam tourism paper only calls it a megalith site, so the stored -1000 has no support and the field is emptied.", "value_page": null}]'::jsonb),
    ('bebaa4d3-fb8e-46a4-b9cb-fe6589925889'::uuid, 'site_type', 'Necropolis/tombs complex', 'Megalithic', 'fields-wd1-2026-09-26b-s008:bebaa4d3-fb8e-46a4-b9cb-fe6589925889:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''Necropolis/tombs complex'' -> ''Megalithic''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=63570", "url": "https://www.megalithic.co.uk/article.php?sid=63570", "quote": "Site Name: Pematang Bango Stone Grave Alternative Name: Talang Kecepol", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=63570", "url": "https://www.megalithic.co.uk/article.php?sid=63570", "quote": "A cist grave around Pagar Alam", "outcome": "found"}, {"source": "https://jrssh.org/index.php/jrssh/article/download/104/pdf", "url": "https://jrssh.org/index.php/jrssh/article/download/104/pdf", "quote": "Relics from the megalithic era in the city of Pagar Alam include the Talang Kecepol Megalith Site, Tanjung Aro Megalithic Site, Lumuai Megalithic Site, Tebing Tinggi Megalithic Site,", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0079)", "decision": "replace", "status": "MISSING", "reasoning": "The Megalithic Portal records the site (alternative name Talang Kecepol) as a single megalithic stone cist grave, and the Pagar Alam cultural-tourism paper lists it as the Talang Kecepol Megalith Site. One stone grave is not a necropolis or tomb complex; no source calls it a tomb in so many words, so the type both sources support is Megalithic.", "value_page": null}]'::jsonb),
    ('bebaa4d3-fb8e-46a4-b9cb-fe6589925889'::uuid, 'source_url', 'https://www.google.com.au/maps/place/Situs+Megalith+Talang+Kecepol/@-4.0258728,103.2056833,19.93z/data=!4m12!1m5!3m4!2zNMKwMDEnMjYuMyJTIDEwM8KwMTInMTkuOSJF!8m2!3d-4.0239789!4d103.2055181!3m5!1s0x2e376b6dcb3750f1:0xb76abbd0b4b36234!8m2!3d-4.0259845!4d103.2058028!16s%2Fg%2F11ckg2y1pq', 'https://www.megalithic.co.uk/article.php?sid=63570', 'fields-wd1-2026-09-26b-s008:bebaa4d3-fb8e-46a4-b9cb-fe6589925889:source_url', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''https://www.google.com.au/maps/place/Situs+Megalith+Talang+Kecepol/@-4.0258728,103.2056833,19.93z/data=!4m12!1m5!3m4!2zNMKwMDEnMjYuMyJTIDEwM8KwMTInMTkuOSJF!8m2!3d-4.0239789!4d103.2055181!3m5!1s0x2e376b6dcb3750f1:0xb76abbd0b4b36234!8m2!3d-4.0259845!4d103.2058028!16s%2Fg%2F11ckg2y1pq'' -> ''https://www.megalithic.co.uk/article.php?sid=63570''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=63570", "url": "https://www.megalithic.co.uk/article.php?sid=63570", "quote": "Site Name: Pematang Bango Stone Grave Alternative Name: Talang Kecepol", "outcome": "found"}, {"source": "https://jrssh.org/index.php/jrssh/article/download/104/pdf", "url": "https://jrssh.org/index.php/jrssh/article/download/104/pdf", "quote": "Relics from the megalithic era in the city of Pagar Alam include the Talang Kecepol Megalith Site, Tanjung Aro Megalithic Site, Lumuai Megalithic Site, Tebing Tinggi Megalithic Site,", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0079)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Google Maps link is not a source. The Megalithic Portal has its own entry for this site (Pematang Bango Stone Grave, alternative name Talang Kecepol, near Pagar Alam) with a GPS point matching the map pin; the Pagar Alam tourism paper independently names the Talang Kecepol Megalith Site.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}