    ('bebb7616-5341-4fd5-a69e-ee430e59c44f'::uuid, 'site_type', 'Mound/tumulus', 'Cairn', 'fields-wd1-2026-09-26b-s008:bebb7616-5341-4fd5-a69e-ee430e59c44f:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''Mound/tumulus'' -> ''Cairn''', '[{"source": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA170256", "url": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA170256", "quote": "A large stone and peat round cairn situated on Margery Hill.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Margery_Hill", "url": "https://en.wikipedia.org/wiki/Margery_Hill", "quote": "Peat near the summit cairn has been dated to a uniform age of about 3,500 years old", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0007)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site at the summit is the scheduled Bronze Age round cairn, not the hill: the National Trust heritage record calls it a large stone and peat round cairn (monument type burial cairn) and Wikipedia speaks of the summit cairn as part of a Bronze Age burial mound; cairn is the more specific canonical type than Mound/tumulus.", "value_page": null}]'::jsonb),
