    ('bf3e61c6-0ecc-4223-949e-86afe1d8d2ac'::uuid, 'period_name', '3000 - 1500 BC', NULL, 'fields-wd1-2026-09-26b-s008:bf3e61c6-0ecc-4223-949e-86afe1d8d2ac:period_name', 'fields-wd1-2026-09-26b-s008 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('bf3e61c6-0ecc-4223-949e-86afe1d8d2ac'::uuid, 'period_start', '-2000', NULL, 'fields-wd1-2026-09-26b-s008:bf3e61c6-0ecc-4223-949e-86afe1d8d2ac:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-clear): ''-2000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0043)", "decision": "clear", "status": "MISSING", "reasoning": "The Dorset HER gives only the broad band ''Iron Age - 800 BC to 42 AD'' and dates a later interior structure to about 80-40 BC; Wikipedia, the Megalithic Portal and the magazine articles call the fort Iron Age without a construction year or century, so no attested start can be quoted.", "value_page": null}]'::jsonb),
    ('bf3e61c6-0ecc-4223-949e-86afe1d8d2ac'::uuid, 'site_type', 'Fortress/citadel', 'Fort', 'fields-wd1-2026-09-26b-s008:bf3e61c6-0ecc-4223-949e-86afe1d8d2ac:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''Fortress/citadel'' -> ''Fort''', '[{"source": "https://heritage.dorsetcouncil.gov.uk/Monument/MDO2018", "url": "https://heritage.dorsetcouncil.gov.uk/Monument/MDO2018", "quote": "Pilsdon Pen Hillfort, a well-preserved multivallate fort of Iron Age date.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=4641", "url": "https://www.megalithic.co.uk/article.php?sid=4641", "quote": "Site Name: Pilsdon Pen Country: England County: Dorset Type: Hillfort", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Pilsdon_Pen", "url": "https://en.wikipedia.org/wiki/Pilsdon_Pen", "quote": "The hill is topped by an Iron Age multivallate Durotrigian hillfort", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0043)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Dorset Historic Environment Record, the Megalithic Portal and Wikipedia all describe the site as an Iron Age multivallate hillfort, which the canonical type Fort holds more exactly than Fortress/citadel.", "value_page": null}]'::jsonb),
    ('bf3e61c6-0ecc-4223-949e-86afe1d8d2ac'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Pilsdon_Pen', 'https://heritage.dorsetcouncil.gov.uk/Monument/MDO2018', 'fields-wd1-2026-09-26b-s008:bf3e61c6-0ecc-4223-949e-86afe1d8d2ac:source_url', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''https://en.wikipedia.org/wiki/Pilsdon_Pen'' -> ''https://heritage.dorsetcouncil.gov.uk/Monument/MDO2018''', '[{"source": "https://heritage.dorsetcouncil.gov.uk/Monument/MDO2018", "url": "https://heritage.dorsetcouncil.gov.uk/Monument/MDO2018", "quote": "Pilsdon Pen Hillfort, a well-preserved multivallate fort of Iron Age date.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=4641", "url": "https://www.megalithic.co.uk/article.php?sid=4641", "quote": "Site Name: Pilsdon Pen Country: England County: Dorset Type: Hillfort", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0043)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is about the hill; no Wikipedia article is about the hillfort except a Cebuano GeoNames bot stub, so the Dorset Council Historic Environment Record entry MDO2018 ''Iron Age hillfort on Pilsdon Pen'', which loads as plain HTML, is the site''s own register page; the Megalithic Portal names the same hillfort independently.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('bf43132d-1cbc-4dd2-9cf9-914a917e78d9'::uuid, 'period_name', '1 - 500 AD', NULL, 'fields-wd1-2026-09-26b-s008:bf43132d-1cbc-4dd2-9cf9-914a917e78d9:period_name', 'fields-wd1-2026-09-26b-s008 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('bf43132d-1cbc-4dd2-9cf9-914a917e78d9'::uuid, 'period_start', '1', NULL, 'fields-wd1-2026-09-26b-s008:bf43132d-1cbc-4dd2-9cf9-914a917e78d9:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-clear): ''1'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0107)", "decision": "clear", "status": "MISSING", "reasoning": "No two independent sources agree on a start: a local radio blog says the remains were built 400 years after Christ, a student field report claims 1200 BC and a possible Middle Horizon date, and the MINCETUR inventory has it built by the Caxamarca against Inca incursions; the stored 1 AD is unsupported.", "value_page": null}]'::jsonb),
    ('bf43132d-1cbc-4dd2-9cf9-914a917e78d9'::uuid, 'site_type', 'City/town/settlement', 'Fort', 'fields-wd1-2026-09-26b-s008:bf43132d-1cbc-4dd2-9cf9-914a917e78d9:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''City/town/settlement'' -> ''Fort''', '[{"source": "https://www.turismoperuano.com/centro-arqueologico-de-collor-cajamarca", "url": "https://www.turismoperuano.com/centro-arqueologico-de-collor-cajamarca", "quote": "Se llegó a la conclusión de que Collor era una ciudad fortificada de carácter militar construida posiblemente por los Caxamarcas para defenderse de las continuas incursiones de los incas", "outcome": "found"}, {"source": "https://www.turismoperuano.com/centro-arqueologico-de-collor-cajamarca", "url": "https://www.turismoperuano.com/centro-arqueologico-de-collor-cajamarca", "quote": "6 km. hasta la fortaleza Collor", "outcome": "found"}, {"source": "https://luisa-turismo.blogspot.com/2011/07/salida-campo-namora.html", "url": "https://luisa-turismo.blogspot.com/2011/07/salida-campo-namora.html", "quote": "Es una fortaleza de carácter militar social donde los cajamarcas en esa época lo utilizaron para organizarse y evitar las invasiones de los grupos pequeños de otros lugares.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0107)", "decision": "replace", "status": "CONFLICT", "reasoning": "Peru''s tourism inventory (MINCETUR, reproduced by turismoperuano.com) describes Collor as a fortified military city with circular defensive towers and calls it the ''fortaleza Collor'', and a Cajamarca tourism field report likewise calls it a military fortress (fortaleza) and citadel of the Cajamarca culture; the sources describe a fortified military stronghold (fort), more specific than a generic settlement.", "value_page": null}]'::jsonb),
    ('bfa06d13-88b7-4e88-913b-1f06f7c5305b'::uuid, 'site_type', 'Megalithic stones', 'Monument', 'fields-wd1-2026-09-26b-s008:bfa06d13-88b7-4e88-913b-1f06f7c5305b:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''Megalithic stones'' -> ''Monument''', '[{"source": "https://es.wikipedia.org/wiki/Estoa_Pecile", "url": "https://es.wikipedia.org/wiki/Estoa_Pecile", "quote": "era un monumento de la antigua Grecia", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Stoa_Poikile", "url": "https://en.wikipedia.org/wiki/Stoa_Poikile", "quote": "or Painted Portico was a Doric stoa (a covered walkway or portico) erected around 460 BC on the north side of the", "outcome": "found"}, {"source": "https://time.com/archive/6858943/steps-of-the-stoa-archaeologists-uncover-a-cornerstone-of-democracy/", "url": "https://time.com/archive/6858943/steps-of-the-stoa-archaeologists-uncover-a-cornerstone-of-democracy/", "quote": "Built around 460 B.C., the Painted Stoa—or Stoa Poikile, as it is also called—was the first important new structure to rise from the ashes of the great Persian invasion, two decades before.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0072)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is a single classical building, the Doric Painted Stoa on the north side of the Athenian Agora, which Spanish Wikipedia calls a monument of ancient Greece and TIME a structure; nothing about it is megalithic and no canonical type names a stoa, so Monument is the most specific fit.", "value_page": null}]'::jsonb),
    ('c1448f84-e07a-436a-8110-087f293a6564'::uuid, 'geom', '0101000020E6100000B1F8EA496D3B234083F316A7502B4A40', 'SRID=4326;POINT(9.639927 52.352423)', 'fields-wd1-2026-09-26b-s008:c1448f84-e07a-436a-8110-087f293a6564:geom', 'fields-wd1-2026-09-26b-s008 (wd1-point): 52.33839882488885, 9.616068181927718 -> 52.352423, 9.639927', '[{"source": "https://www.megalithic.co.uk/article.php?sid=47761", "url": "https://www.megalithic.co.uk/article.php?sid=47761", "quote": "Latitude: 52.352423N Longitude: 9.639927E", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/519614716", "url": "https://www.openstreetmap.org/node/519614716", "quote": "52.3511533, 9.6348204", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0057)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is the Bronze Age barrow cemetery on the north-eastern part of the Benther Berg ridge. The Megalithic Portal places the cemetery at 52.3524, 9.6399 and OpenStreetMap''s information board ''Hügelgräber auf dem Benther Berg'' stands at 52.3512, 9.6348, 0.4 km away. The stored point is the ridge''s summit at its southern end, about 2.2 km from the cemetery, so it is replaced.", "value_page": null}]'::jsonb),
