    ('c1448f84-e07a-436a-8110-087f293a6564'::uuid, 'period_name', '4500 - 3000 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s008:c1448f84-e07a-436a-8110-087f293a6564:period_name', 'fields-wd1-2026-09-26b-s008 (wd1-derive-period-name): period_start -1600 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1600) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('c1448f84-e07a-436a-8110-087f293a6564'::uuid, 'period_start', '-4500', '-1600', 'fields-wd1-2026-09-26b-s008:c1448f84-e07a-436a-8110-087f293a6564:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''-4500'' -> ''-1600''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=47761", "url": "https://www.megalithic.co.uk/article.php?sid=47761", "quote": "Today, the few remaining finds suggest that the cemetery was used in the early Bronze Age (ca. 1600 – 1200 BC).", "outcome": "found"}, {"source": "https://cdn.pressebox.de/a/bdd58f0d26732247/attachments/0229666.attachment/filename/Arch%C3%A4ologie-Infotafeln.pdf", "url": "https://cdn.pressebox.de/a/bdd58f0d26732247/attachments/0229666.attachment/filename/Arch%C3%A4ologie-Infotafeln.pdf", "quote": "Älteren Bronzezeit (1600 - 1200 v. Chr.) angelegt", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0057)", "decision": "replace", "status": "MISSING", "reasoning": "The Megalithic Portal (after Bartelt 2015) and the Lower Saxony heritage office''s information board text both date the barrows to the Older Bronze Age, c. 1600-1200 BC, so the start is c. 1600 BC, not the stored 4500 BC.", "value_page": null}]'::jsonb),
    ('c1448f84-e07a-436a-8110-087f293a6564'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Benther_Berg', 'https://www.megalithic.co.uk/article.php?sid=47761', 'fields-wd1-2026-09-26b-s008:c1448f84-e07a-436a-8110-087f293a6564:source_url', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''https://en.wikipedia.org/wiki/Benther_Berg'' -> ''https://www.megalithic.co.uk/article.php?sid=47761''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=47761", "url": "https://www.megalithic.co.uk/article.php?sid=47761", "quote": "The Grabhügelfeld Benther Berg is a barrow cemetery on the Benther Berg hill in Ronnenberg (Lower Saxony/Germany).", "outcome": "found"}, {"source": "https://de.wikipedia.org/wiki/Benther_Berg", "url": "https://de.wikipedia.org/wiki/Benther_Berg", "quote": "Am Nordost-Hang und auf dem Kamm des Benther Berges existiert zudem ein Feld aus 25 frühgeschichtlichen Hügelgräbern aus der Bronzezeit", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0057)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is about the Benther Berg ridge, the hill the cemetery lies on; the Megalithic Portal entry ''Grabhügelfeld Benther Berg'' is about the barrow cemetery itself, which the German article confirms on the ridge''s north-eastern slope and crest.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('c1542a09-61a1-4e19-bb25-6225cecac965'::uuid, 'site_type', 'City/town/settlement', 'City', 'fields-wd1-2026-09-26b-s008:c1542a09-61a1-4e19-bb25-6225cecac965:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''City/town/settlement'' -> ''City''', '[{"source": "https://en.wikipedia.org/wiki/Caulonia_(ancient_city)", "url": "https://en.wikipedia.org/wiki/Caulonia_(ancient_city)", "quote": "was an ancient city on the shore of the Ionian Sea near Monasterace", "outcome": "found"}, {"source": "https://www.italia.it/en/calabria/reggio-calabria/archaelogical-area-of-kaulonia", "url": "https://www.italia.it/en/calabria/reggio-calabria/archaelogical-area-of-kaulonia", "quote": "The archaeological remains of the ancient city of Kaulonia are located in Monasterace", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0084)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is the ancient Greek city (polis) of Kaulonia, not the museum that now manages it; Wikipedia and the Italian tourism board both call it an ancient city, so the more specific type City replaces City/town/settlement.", "value_page": null}]'::jsonb),
