    ('c2628a93-7c87-4a98-8d13-8301f7063403'::uuid, 'site_type', 'Necropolis/tombs complex', 'Mound/tumulus', 'fields-wd1-2026-09-26b-s008:c2628a93-7c87-4a98-8d13-8301f7063403:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''Necropolis/tombs complex'' -> ''Mound/tumulus''', '[{"source": "https://fr.wikipedia.org/wiki/Tumulus_d%27Er_Grah", "url": "https://fr.wikipedia.org/wiki/Tumulus_d%27Er_Grah", "quote": "Le tumulus d''Er Grah est un tumulus daté du Néolithique situé sur la commune de Locmariaquer, dans le département français du Morbihan.", "outcome": "found"}, {"source": "https://www.site-megalithique-locmariaquer.fr/en/discover/the-er-grah-tumulus", "url": "https://www.site-megalithique-locmariaquer.fr/en/discover/the-er-grah-tumulus", "quote": "Starting out as a small cairn, the architecture was stretched to the north and south to reach a length of almost 140 metres, forming this distinctive trapezoidal structure of stone and earth: a tumulus.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0052)", "decision": "replace", "status": "CONFLICT", "reasoning": "Er Grah is a single 140 m long Neolithic mound over one burial chamber, described as a tumulus by French Wikipedia and by the Centre des monuments nationaux; it is not a necropolis or a complex of tombs, so the specific type is Mound/tumulus.", "value_page": null}]'::jsonb),
    ('c2628a93-7c87-4a98-8d13-8301f7063403'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Locmariaquer_megaliths', 'https://fr.wikipedia.org/wiki/Tumulus_d%27Er_Grah', 'fields-wd1-2026-09-26b-s008:c2628a93-7c87-4a98-8d13-8301f7063403:source_url', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''https://en.wikipedia.org/wiki/Locmariaquer_megaliths'' -> ''https://fr.wikipedia.org/wiki/Tumulus_d%27Er_Grah''', '[{"source": "https://fr.wikipedia.org/wiki/Tumulus_d%27Er_Grah", "url": "https://fr.wikipedia.org/wiki/Tumulus_d%27Er_Grah", "quote": "Le tumulus d''Er Grah est un tumulus daté du Néolithique situé sur la commune de Locmariaquer, dans le département français du Morbihan.", "outcome": "found"}, {"source": "https://archeologie.culture.gouv.fr/megalithes/en/er-grah-tumulus", "url": "https://archeologie.culture.gouv.fr/megalithes/en/er-grah-tumulus", "quote": "Excavations revealed that Er-Grah tumulus was the final achievement of a complex architectural process.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0052)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored article covers the whole Locmariaquer megalith group (another Wikidata item); the tumulus has its own French Wikipedia article, ''Tumulus d''Er Grah'', about this very monument.", "value_page": {"lang": "fr", "problem": null, "resolved_title": "Tumulus d''Er Grah", "unreadable": false, "wikibase_item": "Q1347902"}}]'::jsonb),
    ('c2801c07-a03a-4193-b35f-c775efa04d78'::uuid, 'period_name', '4500 - 3000 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s008:c2801c07-a03a-4193-b35f-c775efa04d78:period_name', 'fields-wd1-2026-09-26b-s008 (wd1-derive-period-name): period_start -1800 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1800) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('c2801c07-a03a-4193-b35f-c775efa04d78'::uuid, 'period_start', '-4500', '-1800', 'fields-wd1-2026-09-26b-s008:c2801c07-a03a-4193-b35f-c775efa04d78:period_start', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''-4500'' -> ''-1800''', '[{"source": "https://www.discovercrete.com/places-to-go/chrysolakkos-in-malia-and-the-double-bee", "url": "https://www.discovercrete.com/places-to-go/chrysolakkos-in-malia-and-the-double-bee", "quote": "At a distance of 500 metres northeast of the palace at the site ‘Chrysolakkos’, the great Paleopalatial Necropolis was excavated. It is a burial space enclosed in a rectangular building with walls made of grey limestone. It is a burial complex with small, rectangular spaces that served as burial chambers. The excavations brought to light gold offerings to the dead as well as a hollow altar with a jagged outline, intended for funeral worship. In one of these places was found the famous gold jewel with the Double Bee. The jewel is a work of Minoan goldsmithing of 1800 - 1700 BC", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Chryssolakkos", "url": "https://en.wikipedia.org/wiki/Chryssolakkos", "quote": "ancient necropolis (royal burial enclosure or cemetery, 1700 BCE) in", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0063)", "decision": "replace", "status": "MISSING", "reasoning": "Chrysolakkos is a Bronze Age Minoan necropolis at Malia, not a Neolithic site: Discover Crete calls it the great Paleopalatial necropolis, whose gold bee pendant dates to 1800-1700 BC, and Wikipedia dates it to 1700 BCE. The start is therefore c. 1800 BC, in the 3000-1500 BC bucket, not the stored -4500 (the French School''s Protopalatial dating, c. 1900-1700 BC, falls in the same bucket).", "value_page": null}]'::jsonb),
    ('c2bbac8e-a9d7-44be-a639-1920ef0dc640'::uuid, 'site_type', 'Megalithic stones', 'Tomb', 'fields-wd1-2026-09-26b-s008:c2bbac8e-a9d7-44be-a639-1920ef0dc640:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''Megalithic stones'' -> ''Tomb''', '[{"source": "https://en.wikipedia.org/wiki/Belevi_Mausoleum", "url": "https://en.wikipedia.org/wiki/Belevi_Mausoleum", "quote": "The Belevi Mausoleum was a grandiose tomb.", "outcome": "found"}, {"source": "https://turkisharchaeonews.net/site/belevi-mausoleum", "url": "https://turkisharchaeonews.net/site/belevi-mausoleum", "quote": "Belevi Mausoleum is a monumental tomb from the Hellenistic era that stands near Selçuk in the Aegean province of Izmir.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0142)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources describe the Belevi Mausoleum as a monumental Hellenistic tomb built for Lysimachus and later used for Antiochus II; it is not a megalithic stone site, so the type becomes Tomb.", "value_page": null}]'::jsonb),
