    ('c3c4e677-a96a-41bc-aea7-7a6882e8dd1a'::uuid, 'site_type', 'City/town/settlement', 'Villa', 'fields-wd1-2026-09-26b-s008:c3c4e677-a96a-41bc-aea7-7a6882e8dd1a:site_type', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''City/town/settlement'' -> ''Villa''', '[{"source": "https://lisboaromana.pt/en/place/roman-villa-of-casais-velhos", "url": "https://lisboaromana.pt/en/place/roman-villa-of-casais-velhos", "quote": "Roman villa that had a particularly intensive occupation during the Low-Imperial era and, probably, during the Late Antiquity.", "outcome": "found"}, {"source": "https://www.cascais.pt/patrimonio-arqueologico-villa-romana-de-casais-velhos", "url": "https://www.cascais.pt/patrimonio-arqueologico-villa-romana-de-casais-velhos", "quote": "Casais Velhos é um sítio arqueológico ocupado durante uma longa diacronia, tendo ali sido implantada uma villa durante o período romano.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0119)", "decision": "replace", "status": "CONFLICT", "reasoning": "Lisboa Romana and the Cascais municipality describe Casais Velhos as a Roman villa (with baths, dyeing tanks and necropoleis), as do the national register and Portuguese Wikipedia; it was not a town, so the type is Villa.", "value_page": null}]'::jsonb),
