    ('c3ed760b-0027-4275-bed0-787ef5d7ef02'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Rame_Head', 'https://www.megalithic.co.uk/article.php?sid=10079', 'fields-wd1-2026-09-26b-s008:c3ed760b-0027-4275-bed0-787ef5d7ef02:source_url', 'fields-wd1-2026-09-26b-s008 (wd1-replace): ''https://en.wikipedia.org/wiki/Rame_Head'' -> ''https://www.megalithic.co.uk/article.php?sid=10079''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=10079", "url": "https://www.megalithic.co.uk/article.php?sid=10079", "quote": "Rame Head promontary fort, Cornwall, SX418482", "outcome": "found"}, {"source": "https://www.transceltic.com/cornwall/rame-head-maker-rame", "url": "https://www.transceltic.com/cornwall/rame-head-maker-rame", "quote": "Known as Rame Head this promontory lies at the south-eastern tip of Cornwall, near to the mouth of the Tamar estuary. Flint tools found in the vicinity of the headland point to the areas occupation from the Mesolithic period. In the Iron Age the headland was separated from the mainland by a ditch and rampart stretching across the isthmus creating a cliff castle.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0044)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the headland (a cape) as a whole; the Megalithic Portal entry is the readable page about the Rame Head promontory fort itself, and Transceltic independently describes the same cliff castle on Rame Head.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb);
